const cleanAcknowledgement = (ack: string, source: string): string => {
  const cleanedAck = ack.trim();
  const cleanedSource = source.trim();

  if (!cleanedSource) return cleanedAck;

  const escapedSource = cleanedSource.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regexEnd = new RegExp(`\\s*\\/\\s*${escapedSource}$`, 'i');
  const regexStart = new RegExp(`^${escapedSource}\\s*\\/\\s*`, 'i');

  let result = cleanedAck;
  if (regexEnd.test(result)) {
    result = result.replace(regexEnd, '');
  } else if (regexStart.test(result)) {
    result = result.replace(regexStart, '');
  }
  return result.trim();
};

const isCoverPage = (pageNumber: string): boolean => {
  const normalizedPageNumber = pageNumber.trim().toLowerCase();

  if (normalizedPageNumber === '') {
    return true;
  }

  const exactMatchKeywords = ['c'];
  if (exactMatchKeywords.includes(normalizedPageNumber)) {
    return true;
  }

  const partialMatchKeywords = [
    'cov',
    'cover',
    'cvr',
    'fc', // Front Cover
    'bc', // Back Cover
    'ifc', // Inside Front Cover
    'ibc', // Inside Back Cover
  ];

  return partialMatchKeywords.some(keyword => normalizedPageNumber.includes(keyword));
};


const processGroup = (records: AcknowledgementRecord[]): { uniqueRecords: AcknowledgementRecord[], duplicates: AcknowledgementRecord[] } => {
  const cleanedRecords = records.map(record => ({
    ...record,
    acknowledgement: cleanAcknowledgement(record.acknowledgement, record.source),
  }));

  const groupedBySource = new Map<string, AcknowledgementRecord[]>();
  cleanedRecords.forEach(record => {
    if (!groupedBySource.has(record.source)) {
      groupedBySource.set(record.source, []);
    }
    groupedBySource.get(record.source)?.push(record);
  });

  const sortedSources = Array.from(groupedBySource.keys()).sort((a, b) => a.localeCompare(b));

  const uniqueRecords: AcknowledgementRecord[] = [];
  const duplicates: AcknowledgementRecord[] = [];

  sortedSources.forEach(source => {
    const sourceRecords = groupedBySource.get(source) || [];
    sourceRecords.sort((a, b) => a.acknowledgement.localeCompare(b.acknowledgement));

    const seenKeys = new Set<string>();
    const sourceLower = source.trim().toLowerCase();

    sourceRecords.forEach(record => {
      let uniqueKey: string;
      if (sourceLower === 'n/a') {
        uniqueKey = `${record.acknowledgement}|${record.description || ''}`;
      } else {
        uniqueKey = record.acknowledgement;
      }

      if (seenKeys.has(uniqueKey)) {
        duplicates.push(record);
      } else {
        seenKeys.add(uniqueKey);
        uniqueRecords.push(record);
      }
    });
  });

  return { uniqueRecords, duplicates };
};


const App: React.FC = () => {
  const [status, setStatus] = useState<AppStatus>('idle');
  const [error, setError] = useState<string | null>(null);
  const [fileName, setFileName] = useState<string>('');
  const [isbn, setIsbn] = useState<string | null>(null);
  const [title, setTitle] = useState<string | null>(null);
  const [originalRecordCount, setOriginalRecordCount] = useState<number>(0);
  const [originalRecords, setOriginalRecords] = useState<AcknowledgementRecord[]>([]);

  const [coverData, setCoverData] = useState<AcknowledgementRecord[]>([]);
  const [nonCoverData, setNonCoverData] = useState<AcknowledgementRecord[]>([]);
  const [removedDuplicates, setRemovedDuplicates] = useState<AcknowledgementRecord[]>([]);
  const [crossCategoryDuplicates, setCrossCategoryDuplicates] = useState<AcknowledgementRecord[]>([]);

  // State for Data Validation
  const [dataValidationFlags, setDataValidationFlags] = useState<AIFlaggedRecord[]>([]);
  const [highlightedRowIndices, setHighlightedRowIndices] = useState<number[]>([]);


  // State for AI Analysis
  const [aiFlags, setAiFlags] = useState<AIFlaggedRecord[]>([]);
  const [aiAnalysisStatus, setAiAnalysisStatus] = useState<AIAnalysisStatus>('idle');


  // State for Contact Sheet Analysis
  const [contactSheetStatus, setContactSheetStatus] = useState<ContactSheetStatus>('idle');
  const [imageAnalysisResults, setImageAnalysisResults] = useState<ImageAnalysisResult[]>([]);
  const [contactSheetError, setContactSheetError] = useState<string | null>(null);
  const [processingProgress, setProcessingProgress] = useState({ current: 0, total: 0 });

  // State for Actions Header & Exporting
  const [copyStatus, setCopyStatus] = useState<'idle' | 'copied'>('idle');
  const [isMerging, setIsMerging] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false); // Final Credits (Word)
  const [isDownloadingSorted, setIsDownloadingSorted] = useState(false); // Sorted Original Log (Excel)
  const [isDownloadingOriginal, setIsDownloadingOriginal] = useState(false); // Original Log (Excel)
  const [isDownloadingAll, setIsDownloadingAll] = useState(false); // All files


  // UI State & File Data State
  const [isInfoPanelOpen, setIsInfoPanelOpen] = useState(true);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [rawData, setRawData] = useState<(string | number)[][]>([]);
  const [activeView, setActiveView] = useState<ActiveView>('credits');
  const [headerRowIndex, setHeaderRowIndex] = useState(-1);
  const [columnIndices, setColumnIndices] = useState<HeaderIndices | null>(null);


  const handleReset = () => {
    setStatus('idle');
    setError(null);
    setFileName('');
    setCoverData([]);
    setNonCoverData([]);
    setRemovedDuplicates([]);
    setCrossCategoryDuplicates([]);
    setDataValidationFlags([]);
    setHighlightedRowIndices([]);
    setAiFlags([]);
    setAiAnalysisStatus('idle');
    setIsbn(null);
    setTitle(null);
    setOriginalRecordCount(0);
    setOriginalRecords([]);
    setRawData([]);
    setContactSheetStatus('idle');
    setImageAnalysisResults([]);
    setContactSheetError(null);
    setProcessingProgress({ current: 0, total: 0 });
    setCopyStatus('idle');
    setIsMerging(false);
    setIsDownloading(false);
    setIsDownloadingSorted(false);
    setIsDownloadingOriginal(false);
    setIsDownloadingAll(false);
    setIsInfoPanelOpen(true);
    setIsEditModalOpen(false);
    setActiveView('credits');
    setHeaderRowIndex(-1);
    setColumnIndices(null);
  };

  const handleProcessFile = useCallback(async (file: File) => {
    setStatus('processing');
    setFileName(file.name);
    setError(null);
    setDataValidationFlags([]);
    setHighlightedRowIndices([]);
    setAiFlags([]);
    setAiAnalysisStatus('idle');
    setIsbn(null);
    setTitle(null);
    setOriginalRecordCount(0);
    setOriginalRecords([]);
    setRawData([]);
    setActiveView('credits');

    try {
      const { records: allRecords, isbn: fileIsbn, title: fileTitle, rawData: allRawData, headerRowIndex, columnIndices } = await processExcelFile(file);

      setHeaderRowIndex(headerRowIndex);
      setColumnIndices(columnIndices);

      const validationFlags = validateData(allRawData, headerRowIndex, columnIndices);
      setDataValidationFlags(validationFlags);
      setHighlightedRowIndices(validationFlags.map(flag => flag.originalRowIndex));


      setOriginalRecords(allRecords);
      setRawData(allRawData);
      setIsbn(fileIsbn);
      setTitle(fileTitle);
      setOriginalRecordCount(allRecords.length);

      const coverRecords = allRecords.filter(r => isCoverPage(r.pageNumber));
      const nonCoverRecords = allRecords.filter(r => !isCoverPage(r.pageNumber));

      const { uniqueRecords: processedCoverData, duplicates: coverDups } = processGroup(coverRecords);
      const { uniqueRecords: processedNonCoverData, duplicates: nonCoverDups } = processGroup(nonCoverRecords);

      setCoverData(processedCoverData);
      setNonCoverData(processedNonCoverData);
      setRemovedDuplicates([...coverDups, ...nonCoverDups].sort((a,b) => a.source.localeCompare(b.source)));

      const coverAckSet = new Set(processedCoverData.map(r => `${r.source}|${r.acknowledgement}`));
      const crossDups = processedNonCoverData.filter(r => coverAckSet.has(`${r.source}|${r.acknowledgement}`));
      setCrossCategoryDuplicates(crossDups);

      // Show results to user immediately
      setStatus('success');

      // Set AI analysis to skipped by default, user can trigger it manually.
      setAiAnalysisStatus('skipped');

    } catch (err) {
      if (err instanceof Error) {
        setError(err.message);
      } else {
        setError('An unexpected error occurred.');
      }
      setStatus('error');
    }
  }, []);

  const handleRunAiAnalysis = async () => {
    setAiAnalysisStatus('running');
    try {
        const allUniqueData = [...coverData, ...nonCoverData];
        if (allUniqueData.length === 0) {
            setAiAnalysisStatus('completed'); // Nothing to analyze
            return;
        }
        const flaggedData = await analyzeAcknowledgements(allUniqueData);
        setAiFlags(flaggedData);
        setAiAnalysisStatus('completed');
    } catch (aiError) {
        console.error("AI analysis failed:", aiError);
        setAiAnalysisStatus('error');
    }
  };

  const findPageNumberFromText = (text: string): string => {
    const numbers = text.match(/\d+/g);
    return numbers ? numbers.join(', ') : 'N/A';
  };

  const getPageNumberFromFilename = (filename: string): string => {
    return filename;
  };

  const fileToBase64 = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = () => {
            const result = reader.result as string;
            // remove the data URL prefix: "data:image/jpeg;base64,"
            resolve(result.split(',')[1]);
        };
        reader.onerror = (error) => reject(error);
    });
  };

  const handleContactSheetReset = useCallback(() => {
    setContactSheetStatus('idle');
    setContactSheetError(null);
    setImageAnalysisResults([]);
    setProcessingProgress({ current: 0, total: 0 });
  }, []);

  const handleProcessContactSheet = useCallback(async (file: File) => {
    setContactSheetStatus('processing');
    setContactSheetError(null);
    setImageAnalysisResults([]);
    setProcessingProgress({ current: 0, total: 0 });

    try {
        const extractedImages: ExtractedImage[] = await processContactSheet(file);

        setContactSheetStatus('describing');
        setProcessingProgress({ current: 0, total: extractedImages.length });

        const currentResults: ImageAnalysisResult[] = extractedImages.map(image => ({
            pageNumber: findPageNumberFromText(image.associatedText),
            description: 'Processing...',
            status: 'processing',
            mimeType: image.mimeType,
            imageBase64: image.imageBase64,
        }));
        setImageAnalysisResults(currentResults);

        const CONCURRENCY_LIMIT = 2;
        let completedCount = 0;
        const queue = [...extractedImages.entries()];

        const worker = async () => {
            while (queue.length > 0) {
                const item = queue.shift();
                if (!item) continue;

                const [index, image] = item;

                try {
                    const description = await describeImage(image.imageBase64, image.mimeType);
                    currentResults[index] = { ...currentResults[index], description, status: 'success' };
                } catch (err) {
                     const errorMessage = err instanceof Error ? err.message : "An unknown error occurred.";
                     currentResults[index] = { ...currentResults[index], description: `Gemini AI image description failed: ${errorMessage}`, status: 'error' };
                }
                completedCount++;
                setProcessingProgress({ current: completedCount, total: extractedImages.length });
                setImageAnalysisResults([...currentResults]);
            }
        };

        const workers = Array(CONCURRENCY_LIMIT).fill(null).map(worker);
        await Promise.all(workers);

        setContactSheetStatus('success');

    } catch (err) {
        if (err instanceof Error) {
            setContactSheetError(err.message);
        } else {
            setContactSheetError('An unexpected error occurred during contact sheet processing.');
        }
        setContactSheetStatus('error');
    }
  }, []);

  const handleProcessDirectImages = useCallback(async (files: File[]) => {
    setContactSheetStatus('describing');
    setContactSheetError(null);
    setProcessingProgress({ current: 0, total: files.length });

    const currentResults: ImageAnalysisResult[] = files.map(file => ({
        pageNumber: getPageNumberFromFilename(file.name),
        description: 'Processing...',
        status: 'processing',
        mimeType: file.type,
        imageBase64: '',
    }));
    setImageAnalysisResults(currentResults);

    const CONCURRENCY_LIMIT = 2;
    let completedCount = 0;
    const queue = [...files.entries()];

    const worker = async () => {
        while(queue.length > 0) {
            const item = queue.shift();
            if (!item) continue;

            const [index, file] = item;

            try {
                const base64 = await fileToBase64(file);
                currentResults[index].imageBase64 = base64;
                const description = await describeImage(base64, file.type);
                currentResults[index] = { ...currentResults[index], description, status: 'success' };
            } catch (err) {
                 const errorMessage = err instanceof Error ? err.message : "An unknown error occurred.";
                 currentResults[index] = { ...currentResults[index], description: `Gemini AI image description failed: ${errorMessage}`, status: 'error' };
            }
            completedCount++;
            setProcessingProgress({ current: completedCount, total: files.length });
            setImageAnalysisResults([...currentResults]);
        }
    };

    const workers = Array(CONCURRENCY_LIMIT).fill(null).map(worker);
    await Promise.all(workers);

    setContactSheetStatus('success');
  }, []);

  const handleRetryFailedImages = useCallback(async () => {
    const failedImages = imageAnalysisResults.filter(r => r.status === 'error');
    if (failedImages.length === 0) return;

    setContactSheetStatus('describing');
    const totalRetries = failedImages.length;
    const totalOriginal = imageAnalysisResults.length;
    const completedOriginal = totalOriginal - imageAnalysisResults.filter(r => r.status !== 'success').length;

    setProcessingProgress({ current: completedOriginal, total: totalOriginal });

    // FIX: Add explicit type annotation to prevent type widening of the `status` property.
    const updatedResults: ImageAnalysisResult[] = imageAnalysisResults.map(r => r.status === 'error' ? { ...r, description: 'Retrying...', status: 'processing' } : r);
    setImageAnalysisResults(updatedResults);

    const CONCURRENCY_LIMIT = 2;
    let completedRetries = 0;
    const queue = [...failedImages];

    const worker = async () => {
        while(queue.length > 0) {
            const imageToRetry = queue.shift();
            if (!imageToRetry) continue;

            const originalIndex = updatedResults.findIndex(r => r.pageNumber === imageToRetry.pageNumber && r.status === 'processing');
            if (originalIndex === -1) continue;

            try {
                const description = await describeImage(imageToRetry.imageBase64, imageToRetry.mimeType);
                updatedResults[originalIndex] = { ...imageToRetry, description, status: 'success' };
            } catch (err) {
                 const errorMessage = err instanceof Error ? err.message : "An unknown error occurred.";
                 updatedResults[originalIndex] = { ...imageToRetry, description: `Gemini AI image description failed: ${errorMessage}`, status: 'error' };
            }
            completedRetries++;
            setProcessingProgress({ current: completedOriginal + completedRetries, total: totalOriginal });
            setImageAnalysisResults([...updatedResults]);
        }
    };

    const workers = Array(CONCURRENCY_LIMIT).fill(null).map(worker);
    await Promise.all(workers);

    setContactSheetStatus('success');
  }, [imageAnalysisResults]);

  // Action handlers
  const sanitizeFilename = (name: string): string => {
    let sanitized = name.replace(/\s+/g, '_');
    sanitized = sanitized.replace(/[^a-zA-Z0-9_.-]/g, '_');
    return sanitized;
  };

  const handleCopy = () => {
      let tsvContent = "Source\tAcknowledgement\tPage Number\n";

      if (coverData.length > 0) {
          tsvContent += "--- Cover Credits ---\n";
          tsvContent += coverData.map(row => `${row.source}\t${row.acknowledgement}\t${row.pageNumber}`).join('\n') + '\n';
      }
      if (nonCoverData.length > 0) {
          tsvContent += "--- Main Content Credits ---\n";
          tsvContent += nonCoverData.map(row => `${row.source}\t${row.acknowledgement}\t${row.pageNumber}`).join('\n') + '\n';
      }

      if (removedDuplicates.length > 0) {
          tsvContent += "\n--- Removed Duplicates ---\n";
          tsvContent += removedDuplicates.map(row => `${row.source}\t${row.acknowledgement}\t(Page: ${row.pageNumber})`).join('\n') + '\n';
      }

      if (crossCategoryDuplicates.length > 0) {
          tsvContent += "\n--- Note: Acknowledgements in Both Cover and Main Content ---\n";
          tsvContent += crossCategoryDuplicates.map(row => `${row.source}\t${row.acknowledgement}`).join('\n') + '\n';
      }

      navigator.clipboard.writeText(tsvContent).then(() => {
          setCopyStatus('copied');
          setTimeout(() => setCopyStatus('idle'), 2000);
      }).catch(err => {
          console.error('Failed to copy text: ', err);
          alert('Failed to copy data to clipboard.');
      });
  };

  // --- REUSABLE GENERATION HELPERS ---

  const generateWordBlob = async (): Promise<Blob> => {
      const defaultStyles = { font: "Calibri", size: 22 }; // size 22 in docx half-points = 11pt

      const formatGroupToRuns = (data: AcknowledgementRecord[]): any[] => {
          if (!data.length) return [];

          const groupedBySource = new Map<string, string[]>();
          data.forEach(record => {
              const source = record.source;
              if (!groupedBySource.has(source)) {
                  groupedBySource.set(source, []);
              }
              groupedBySource.get(source)!.push(record.acknowledgement);
          });

          const runs: any[] = [];
          const sortedSources = Array.from(groupedBySource.keys());

          sortedSources.forEach((source, index) => {
              const acks = groupedBySource.get(source)!;
              const ackString = acks.join(', ');

              runs.push(new TextRun({ text: source, bold: true, ...defaultStyles }));
              runs.push(new TextRun({ text: " ", ...defaultStyles }));
              runs.push(new TextRun({ text: "(", bold: true, ...defaultStyles }));
              runs.push(new TextRun({ text: ackString, ...defaultStyles }));
              runs.push(new TextRun({ text: ")", bold: true, ...defaultStyles }));

              if (index === sortedSources.length - 1) {
                  runs.push(new TextRun({ text: ".", ...defaultStyles }));
              } else {
                  runs.push(new TextRun({ text: "; ", bold: true, ...defaultStyles }));
              }
          });

          return runs;
      };

      const paragraphs = [
          new Paragraph({
              alignment: AlignmentType.CENTER,
              children: [new TextRun({ text: "Acknowledgements", bold: true, ...defaultStyles })],
          }),
          new Paragraph({ children: [new TextRun({ text: "", ...defaultStyles })] }),
      ];

      if (aiAnalysisStatus === 'completed' && aiFlags.length > 0) {
          paragraphs.push(new Paragraph({
              children: [new TextRun({ text: "Data Quality Warning", bold: true, ...defaultStyles })]
          }));
          paragraphs.push(new Paragraph({
              children: [new TextRun({ text: "The AI analysis flagged the following entries as potential errors. Please review them carefully:", ...defaultStyles })]
          }));
          aiFlags.forEach(flag => {
              paragraphs.push(new Paragraph({
                  bullet: { level: 0 },
                  children: [
                      new TextRun({ text: `Source: `, bold: true, ...defaultStyles }),
                      new TextRun({ text: `${flag.source}, `, ...defaultStyles }),
                      new TextRun({ text: `Acknowledgement: `, bold: true, ...defaultStyles }),
                      new TextRun({ text: `${flag.acknowledgement}, `, ...defaultStyles }),
                      new TextRun({ text: `Page: `, bold: true, ...defaultStyles }),
                      new TextRun({ text: `${flag.pageNumber}. `, ...defaultStyles }),
                      new TextRun({ text: `Reason: `, bold: true, break: 1, ...defaultStyles }),
                      new TextRun({ text: flag.reason, italics: true, ...defaultStyles }),
                  ]
              }));
          });
          paragraphs.push(new Paragraph({ children: [new TextRun({ text: "", ...defaultStyles })] }));
      }

      const coverRuns = formatGroupToRuns(coverData);
      if (coverRuns.length > 0) {
          paragraphs.push(new Paragraph({
              children: [ new TextRun({ text: "Cover: ", bold: true, ...defaultStyles }), ...coverRuns ]
          }));
      }

      const nonCoverRuns = formatGroupToRuns(nonCoverData);
      if (nonCoverRuns.length > 0) {
          if (coverRuns.length > 0) {
              paragraphs.push(new Paragraph({ children: [new TextRun({ text: "", ...defaultStyles })] }));
          }
          paragraphs.push(new Paragraph({ children: nonCoverRuns }));
      }

      const doc = new Document({
          sections: [{ children: paragraphs }],
      });

      return await Packer.toBlob(doc);
  };

  const generateExcelWorkbook = (data: (string | number)[][], titleStr: string, applyStyle: boolean = true) => {
    // @ts-ignore
    const XLSX = window.XLSX;
    const worksheet = XLSX.utils.aoa_to_sheet(data);

    if (applyStyle) {
        const range = XLSX.utils.decode_range(worksheet['!ref']);
        const borderStyle = { style: 'thin', color: { auto: 1 } };
        const border = { top: borderStyle, bottom: borderStyle, left: borderStyle, right: borderStyle };
        const headerFill = { fgColor: { rgb: "C6E0B4" } }; // Light Green

        for (let R = range.s.r; R <= range.e.r; ++R) {
            for (let C = range.s.c; C <= range.e.c; ++C) {
                const cellAddress = XLSX.utils.encode_cell({ r: R, c: C });
                if (!worksheet[cellAddress]) continue;

                if (!worksheet[cellAddress].s) worksheet[cellAddress].s = {};

                worksheet[cellAddress].s.alignment = { wrapText: true, vertical: 'top' };
                worksheet[cellAddress].s.border = border;

                if (headerRowIndex !== -1 && R === headerRowIndex) {
                    worksheet[cellAddress].s.fill = headerFill;
                    worksheet[cellAddress].s.font = { bold: true };
                    worksheet[cellAddress].s.alignment = { wrapText: true, vertical: 'center', horizontal: 'center' };
                }
            }
        }

        if (headerRowIndex !== -1) {
            if (!worksheet['!rows']) worksheet['!rows'] = [];
            for (let i = 0; i <= headerRowIndex; i++) {
                 if (!worksheet['!rows'][i]) worksheet['!rows'][i] = {};
            }
            worksheet['!rows'][headerRowIndex] = { hpx: 40 };
        }

        const colWidths = [];
        const maxCol = range.e.c;
        for (let i = 0; i <= maxCol; i++) {
            if (i >= 9 && i <= 15) { // J=9 to P=15 are narrow
                 colWidths.push({ wch: 4 }); 
            } else if (columnIndices) {
                 if (i === columnIndices.sourceColIndex) colWidths.push({ wch: 40 });
                 else if (i === columnIndices.ackColIndex) colWidths.push({ wch: 60 });
                 else if (i === columnIndices.descColIndex) colWidths.push({ wch: 60 });
                 else if (i === columnIndices.pageColIndex) colWidths.push({ wch: 15 });
                 else if (i === columnIndices.notesColIndex) colWidths.push({ wch: 40 });
                 else if (i === columnIndices.imgNoColIndex) colWidths.push({ wch: 25 });
                 else if (i === columnIndices.feeColIndex) colWidths.push({ wch: 15 });
                 else if (i === columnIndices.usageColIndex) colWidths.push({ wch: 25 });
                 else if (i === columnIndices.rightsColIndex) colWidths.push({ wch: 15 });
                 else colWidths.push({ wch: 20 });
            } else {
                 colWidths.push({ wch: 20 });
            }
        }
        worksheet['!cols'] = colWidths;
    }

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, titleStr);
    return workbook;
  };

  const handleDownloadWord = async () => {
      if (isDownloading) return;
      setIsDownloading(true);
      try {
          const blob = await generateWordBlob();
          let docName = "Final_Credits.docx";
          if (isbn && title) {
              const sanitizedTitle = sanitizeFilename(title);
              docName = `Final_Credits_${isbn}_${sanitizedTitle}.docx`;
          }
          saveAs(blob, docName);
      } catch (err) {
          console.error('Failed to generate Word document:', err);
          alert('Failed to generate Word document.');
      } finally {
          setIsDownloading(false);
      }
  };

  const handleMergeAndDownload = async () => {
      if (isMerging) return;
      setIsMerging(true);
      try {
          // @ts-ignore
          const XLSX = window.XLSX;
          const originalCredits = [...coverData, ...nonCoverData];
          const imageCredits = imageAnalysisResults;
          const headers = ["Acknowledgement", "Page Number", "Image Filename", "AI Description"];
          const mergedRows = [];
          const maxRows = Math.max(originalCredits.length, imageCredits.length);
          for (let i = 0; i < maxRows; i++) {
              const original = originalCredits[i];
              const image = imageCredits[i];
              mergedRows.push([
                  original ? original.acknowledgement : '',
                  original ? original.pageNumber : '',
                  image ? image.pageNumber : '',
                  image ? image.description : '',
              ]);
          }
          const worksheet = XLSX.utils.aoa_to_sheet([headers, ...mergedRows]);
          worksheet['!cols'] = [ { wch: 50 }, { wch: 15 }, { wch: 40 }, { wch: 80 } ];
          const workbook = XLSX.utils.book_new();
          XLSX.utils.book_append_sheet(workbook, worksheet, "Merged Credits");
          let docName = "Merged_Credits_Data.xlsx";
          if (isbn && title) {
              const sanitizedTitle = sanitizeFilename(title);
              docName = `Merged_Credits_${isbn}_${sanitizedTitle}.xlsx`;
          }
          XLSX.writeFile(workbook, docName);
      } catch (err) {
          console.error("Failed to merge and download Excel file:", err);
          alert("An unknown error occurred while generating the merged Excel file.");
      } finally {
          setIsMerging(false);
      }
  };

  const handleDownloadSortedOriginal = async () => {
      if (isDownloadingSorted) return;
      setIsDownloadingSorted(true);
      try {
          // @ts-ignore
          const XLSX = window.XLSX;
          const metadataRows = rawData.slice(0, headerRowIndex);
          const headers = rawData[headerRowIndex];
          const dataRows = rawData.slice(headerRowIndex + 1);
          const filteredDataRows = dataRows.filter(row => row.some(cell => cell !== null && cell !== undefined && cell !== ''));
          const sortedDataRows = [...filteredDataRows].sort((a, b) => {
              const sourceA = String(a[columnIndices!.sourceColIndex] || '');
              const sourceB = String(b[columnIndices!.sourceColIndex] || '');
              const ackA = String(a[columnIndices!.ackColIndex] || '');
              const ackB = String(b[columnIndices!.ackColIndex] || '');
              const sourceCompare = sourceA.localeCompare(sourceB);
              if (sourceCompare !== 0) return sourceCompare;
              return ackA.localeCompare(ackB);
          });
          const finalData = [...metadataRows, headers, ...sortedDataRows];
          const workbook = generateExcelWorkbook(finalData, "Sorted Original Log");
          let docName = "Sorted_Original_Log.xlsx";
          if (isbn && title) {
              const sanitizedTitle = sanitizeFilename(title);
              docName = `Sorted_Original_Log_${isbn}_${sanitizedTitle}.xlsx`;
          }
          XLSX.writeFile(workbook, docName);
      } catch (err) {
          console.error("Failed to generate sorted original Excel file:", err);
          alert("An unknown error occurred while generating the sorted original Excel file.");
      } finally {
          setIsDownloadingSorted(false);
      }
  };

  const handleDownloadOriginal = async () => {
      if (isDownloadingOriginal) return;
      setIsDownloadingOriginal(true);
      try {
          // @ts-ignore
          const XLSX = window.XLSX;
          const workbook = generateExcelWorkbook(rawData, "Original Log");
          let docName = "Original_Log.xlsx";
          if (isbn && title) {
              const sanitizedTitle = sanitizeFilename(title);
              docName = `Original_Log_${isbn}_${sanitizedTitle}.xlsx`;
          }
          XLSX.writeFile(workbook, docName);
      } catch (err) {
          console.error("Failed to download original log:", err);
          alert("An unknown error occurred while downloading the original log.");
      } finally {
          setIsDownloadingOriginal(false);
      }
  };

  const handleDownloadAll = async () => {
      if (isDownloadingAll) return;
      setIsDownloadingAll(true);
      try {
          // @ts-ignore
          const JSZip = window.JSZip;
          if (!JSZip) {
              throw new Error("JSZip library not found.");
          }
          const zip = new JSZip();

          // 1. Generate Word Blob
          const wordBlob = await generateWordBlob();

          // 2. Generate Sorted Excel Blob
          const metadataRows = rawData.slice(0, headerRowIndex);
          const headers = rawData[headerRowIndex];
          const dataRows = rawData.slice(headerRowIndex + 1);
          const filteredDataRows = dataRows.filter(row => row.some(cell => cell !== null && cell !== undefined && cell !== ''));
          const sortedDataRows = [...filteredDataRows].sort((a, b) => {
              const sourceA = String(a[columnIndices!.sourceColIndex] || '');
              const sourceB = String(b[columnIndices!.sourceColIndex] || '');
              const ackA = String(a[columnIndices!.ackColIndex] || '');
              const ackB = String(b[columnIndices!.ackColIndex] || '');
              const sourceCompare = sourceA.localeCompare(sourceB);
              if (sourceCompare !== 0) return sourceCompare;
              return ackA.localeCompare(ackB);
          });
          const sortedExcelWB = generateExcelWorkbook([...metadataRows, headers, ...sortedDataRows], "Sorted Original Log");

          // 3. Generate Original Excel Blob
          const originalExcelWB = generateExcelWorkbook(rawData, "Original Log");

          // Convert workbooks to binary buffers for JSZip
          // @ts-ignore
          const XLSX = window.XLSX;
          const sortedExcelBuf = XLSX.write(sortedExcelWB, { bookType: 'xlsx', type: 'array' });
          const originalExcelBuf = XLSX.write(originalExcelWB, { bookType: 'xlsx', type: 'array' });

          // Determine filenames
          const baseName = (isbn && title) ? `${isbn}_${sanitizeFilename(title)}` : "Credits_Data";

          zip.file(`Final_Credits_${baseName}.docx`, wordBlob);
          zip.file(`Sorted_Original_Log_${baseName}.xlsx`, sortedExcelBuf);
          zip.file(`Original_Log_${baseName}.xlsx`, originalExcelBuf);

          const zipBlob = await zip.generateAsync({ type: "blob" });
          saveAs(zipBlob, `Bundle_${baseName}.zip`);

      } catch (e) {
          console.error("Error during 'Download All' operation:", e);
          alert("An error occurred while trying to bundle your files into a ZIP archive.");
      } finally {
          setIsDownloadingAll(false);
      }
  };

  const handleEditOriginal = () => {
    if (rawData.length > 0) {
      setIsEditModalOpen(true);
    }
  };

  const totalSources = new Set([...coverData.map(d => d.source), ...nonCoverData.map(d => d.source)]).size;

  const renderContent = () => {
    switch (status) {
      case 'idle':
        return (
          <div className="bg-white rounded-xl shadow-lg p-4 sm:p-8">
            <FileUpload onFileSelect={handleProcessFile} />
          </div>
        );
      case 'processing':
        return (
          <div className="bg-white rounded-xl shadow-lg p-4 sm:p-8">
            <div className="text-center p-10">
              <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mx-auto"></div>
              <p className="mt-4 text-slate-600 font-semibold">Processing your file...</p>
            </div>
          </div>
        );
      case 'success':
        return (
          <>
            <div className="flex gap-6">
              <div className="flex-grow bg-white rounded-xl shadow-lg p-2 sm:p-3 flex gap-6 transition-all duration-300">
                <NavigationRail
                    activeView={activeView}
                    onNavigate={setActiveView}
                    dataValidationIssues={dataValidationFlags.length}
                />
                <div className="flex-grow min-w-0">
                  <div className="flex justify-end items-center mb-2 px-2">
                      {activeView === 'credits' && (
                        <button
                            onClick={handleEditOriginal}
                            className="flex items-center gap-2 px-3 py-1.5 bg-white text-slate-600 font-semibold rounded-lg border border-slate-300 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-blue-400 focus:ring-opacity-75 transition-colors text-sm shadow-sm"
                        >
                            <EditIcon className="w-4 h-4" />
                            <span>Edit Original Log</span>
                        </button>
                      )}
                  </div>

                  {activeView === 'credits' && (
                    <ResultsTable 
                      coverData={coverData}
                      nonCoverData={nonCoverData}
                      dataValidationFlags={dataValidationFlags}
                    />
                  )}

                  {activeView === 'analysis' && (
                    <AnalysisView
                        onProcessContactSheet={handleProcessContactSheet}
                        onProcessDirectImages={handleProcessDirectImages}
                        onResetContactSheet={handleContactSheetReset}
                        contactSheetStatus={contactSheetStatus}
                        imageAnalysisResults={imageAnalysisResults}
                        contactSheetError={contactSheetError}
                        processingProgress={processingProgress}
                        onRetryFailedImages={handleRetryFailedImages}
                    />
                  )}

                  {activeView === 'history' && (
                      <div className="p-8 text-center text-slate-500">
                          <h2 className="text-xl font-semibold">Coming Soon</h2>
                          <p>This section is under development.</p>
                      </div>
                  )}

                </div>
              </div>
              <InfoPanel 
                isOpen={isInfoPanelOpen}
                onToggle={() => setIsInfoPanelOpen(!isInfoPanelOpen)}
                fileName={fileName}
                originalRecordCount={originalRecordCount}
                totalSources={totalSources}
                coverCreditsCount={coverData.length}
                mainCreditsCount={nonCoverData.length}
                removedDuplicates={removedDuplicates}
                crossCategoryDuplicates={crossCategoryDuplicates}
              />
            </div>

            <DataHealthModal
                isOpen={activeView === 'dataHealth'}
                onClose={() => setActiveView('credits')}
                dataValidationFlags={dataValidationFlags}
                aiAnalysisStatus={aiAnalysisStatus}
                aiFlags={aiFlags}
                onRunAiAnalysis={handleRunAiAnalysis}
                originalRecordCount={originalRecordCount}
            />

            <ExportModal
                isOpen={activeView === 'export'}
                onClose={() => setActiveView('credits')}
                onDownloadWord={handleDownloadWord}
                onDownloadSortedLog={handleDownloadSortedOriginal}
                onDownloadOriginalLog={handleDownloadOriginal}
                onDownloadAll={handleDownloadAll}
                isDownloading={isDownloading}
                isDownloadingSorted={isDownloadingSorted}
                isDownloadingOriginal={isDownloadingOriginal}
                isDownloadingAll={isDownloadingAll}
            />

            {isEditModalOpen && (
              <EditableLogModal
                  isOpen={isEditModalOpen}
                  onClose={() => setIsEditModalOpen(false)}
              />
            )}
          </>
        );
      case 'error':
        return (
          <div className="bg-white rounded-xl shadow-lg p-4 sm:p-8">
            <div className="text-center p-10 bg-red-50 rounded-lg">
              <ErrorIcon className="w-16 h-16 text-red-500 mx-auto mb-4" />
              <h3 className="text-xl font-semibold text-red-700">Processing Failed</h3>
              <p className="text-slate-600 mt-2 mb-6">{error}</p>
              <button
                onClick={handleReset}
                className="px-6 py-2 bg-blue-600 text-white font-semibold rounded-lg shadow-md hover:bg-blue-700"
              >
                Try Again
              </button>
            </div>
          </div>
        );
    }
  };

  const menuItems = [
    { label: 'Process Another file', onClick: handleReset },
    { label: 'Help', onClick: () => {} }
  ];

  return (
    <main className="container mx-auto p-4 sm:p-6">
      <header className="mb-4 flex justify-between items-center">
        <div className="flex items-center gap-4">
          <DropdownMenu items={menuItems} />
          <div className="text-left">

            <h1 className="text-3xl font-bold text-slate-800">A.M.H</h1>
            <p className="text-slate-500"></p>
          </div>
        </div>
        {status === 'success' && (
          <div className="flex items-center gap-6">
            <div className="text-right min-w-0">
              {isbn && title && (
                <p
                  className="text-lg font-semibold text-slate-800 truncate max-w-lg"
                  title={`${isbn}_${title}`}
                >
                  {`${isbn}_${title}`}
                </p>
              )}
            </div>
            <ActionsHeader 
              isMerging={isMerging}
              copyStatus={copyStatus}
              contactSheetStatus={contactSheetStatus}
              imageAnalysisResults={imageAnalysisResults}
              onMergeAndDownload={handleMergeAndDownload}
              onCopy={handleCopy}
            />
          </div>
        )}
      </header>
      {renderContent()}
    </main>
  );
};

export default App;

import type { AIFlaggedRecord, HeaderIndices } from '../types';

const normalizeText = (text: string): string => {
    // Treat hyphens, slashes as word separators and ignore case.
    return (text || '').toLowerCase().replace(/[-/]/g, ' ');
};

/**
 * Validates records based on a set of concrete rules.
 * @param rawData - The raw data array from the Excel sheet.
 * @param headerRowIndex - The index of the header row.
 * @param columnIndices - An object mapping column names to their indices.
 * @returns An array of flagged records with reasons for the flag.
 */
export const validateData = (
    rawData: (string | number)[][],
    headerRowIndex: number,
    columnIndices: HeaderIndices
): AIFlaggedRecord[] => {
    // Use a temporary type for the map to hold the array of reasons
    type TempFlaggedRecord = AIFlaggedRecord & { reasons: string[] };
    const recordsMap = new Map<number, TempFlaggedRecord>();
    const REASON_SEPARATOR = '|||';

    const getOrCreateFlaggedRecord = (rowIndex: number): TempFlaggedRecord => {
        if (recordsMap.has(rowIndex)) {
            return recordsMap.get(rowIndex)!;
        }
        const row = rawData[rowIndex];
        const record: TempFlaggedRecord = {
            source: String(row[columnIndices.sourceColIndex] || '').trim(),
            acknowledgement: String(row[columnIndices.ackColIndex] || '').trim(),
            pageNumber: String(row[columnIndices.pageColIndex] || '').trim(),
            usageClassification: String(row[columnIndices.usageColIndex] || '').trim(),
            licenseFee: String(row[columnIndices.feeColIndex] || '').trim(),
            originalRowIndex: rowIndex,
            reason: '', // Will be populated at the end
            reasons: [],
        };
        recordsMap.set(rowIndex, record);
        return record;
    };

    // Find the last row that is considered a valid entry.
    // A valid entry is defined as having both a 'Source' and 'Acknowledgement' that are not empty or just a ".".
    // This prevents flagging trailing empty or placeholder rows.
    let lastDataRowIndex = -1;
    for (let i = rawData.length - 1; i > headerRowIndex; i--) {
        const row = rawData[i];
        if (Array.isArray(row)) {
            const sourceCell = row[columnIndices.sourceColIndex];
            const ackCell = row[columnIndices.ackColIndex];

            const source = (sourceCell === null || sourceCell === undefined) ? '' : String(sourceCell).trim();
            const acknowledgement = (ackCell === null || ackCell === undefined) ? '' : String(ackCell).trim();

            // A row is considered to have content if both source and ack are not empty and not just a dot.
            const hasSource = source !== '' && source !== '.';
            const hasAck = acknowledgement !== '' && acknowledgement !== '.';

            if (hasSource && hasAck) {
                lastDataRowIndex = i;
                break;
            }
        }
    }

    if (lastDataRowIndex === -1) {
        return []; // No data rows found to validate.
    }

    // --- ROW-BY-ROW VALIDATION ---
    for (let i = headerRowIndex + 1; i <= lastDataRowIndex; i++) {
        const row = rawData[i];
        if (!Array.isArray(row)) continue;

        const source = String(row[columnIndices.sourceColIndex] || '').trim();
        const rightsType = String(row[columnIndices.rightsColIndex] || '').trim().toUpperCase();
        const notes = String(row[columnIndices.notesColIndex] || '').trim().toLowerCase();

        // JC comments rule: "needs replacing as per pickup" (or "pick-up") exception
        const isReplacingAsPerPickup = notes.includes('needs replacing as per pickup') || notes.includes('needs replacing as per pick-up');

        // FIX: Handle the number 0 correctly, preventing it from being treated as a falsy/empty value.
        const licenseFeeValue = row[columnIndices.feeColIndex];
        const licenseFeeStr = (licenseFeeValue === null || licenseFeeValue === undefined) ? '' : String(licenseFeeValue).trim();

        const licenseFee = parseFloat(licenseFeeStr);
        const usageClassification = String(row[columnIndices.usageColIndex] || '').trim();
        const normalizedUsage = normalizeText(usageClassification);
        const sourceLower = source.toLowerCase();
        const isLicensed = normalizedUsage.includes('license') && !normalizedUsage.includes('no license');

        // --- License-Dependent Fee Validation ---
        if (isLicensed) {
            // Apply rules for licensed usage
            if (sourceLower === 'shutterstock') {
                if (rightsType === 'RF' && licenseFee !== 10) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Shutterstock/RF, fee must be 10, but is "${licenseFeeStr}".`);
                } else if (rightsType === 'RM' && licenseFee !== 40) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Shutterstock/RM, fee must be 40, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'getty images') {
                if (rightsType === 'RF' && licenseFee !== 17.5) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Getty Images/RF, fee must be 17.5, but is "${licenseFeeStr}".`);
                } else if (rightsType === 'RM' && licenseFee !== 40) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Getty Images/RM, fee must be 40, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'alamy') {
                if (licenseFeeStr !== '' && ![0, 29, 45].includes(licenseFee)) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Alamy, licensed fee must be 0, 29, or 45, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'oup') {
                // This is an invalid state for OUP as per rules
                getOrCreateFlaggedRecord(i).reasons.push(`For OUP, Usage must not contain "License", but is "${usageClassification}".`);
            } else {
                // Generic rule for other licensed vendors
                if (licenseFeeStr === '' || isNaN(licenseFee) || licenseFee <= 0) {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is licensed but Licence Fee ("${licenseFeeStr || 'empty'}") is not a positive number.`);
                }
            }
        } else { // Not licensed
            // For non-licensed items, the fee depends on whether it's 'new' or 'pickup'.
            if (normalizedUsage.includes('new') && normalizedUsage.includes('no license')) {
                // For "New/No License", the fee must be 0...
                // UNLESS it's flagged in Notes as "needs replacing as per pickup"
                if (isReplacingAsPerPickup) {
                    // If it is replacing as per pickup, it doesn't need 0, but it should be blank like a normal pickup.
                    if (licenseFeeStr !== '') {
                        getOrCreateFlaggedRecord(i).reasons.push(`For New/No License usage marked "Replacing as per pickup", fee must be blank, but is "${licenseFeeStr}".`);
                    }
                } else {
                    if (licenseFee !== 0) {
                        getOrCreateFlaggedRecord(i).reasons.push(`For New/No License usage, fee must be 0, but is "${licenseFeeStr}".`);
                    }
                }
            } else if ((normalizedUsage.includes('pickup') || normalizedUsage.includes('pick up')) && normalizedUsage.includes('no license')) {
                // For "Pickup/No License", the fee must be blank.
                if (licenseFeeStr !== '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Pickup/No License usage, fee must be blank, but is "${licenseFeeStr}".`);
                }
            } else {
                // Fallback for other non-licensed cases (e.g., if neither "new" nor "pickup" is specified).
                // A fee is unexpected, so we'll flag any non-blank value.
                if (licenseFeeStr !== '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is not licensed and not specified as New/Pickup, but Licence Fee is not empty ("${licenseFeeStr}").`);
                }
            }
        }

        // --- OUP Invariant Check (applies regardless of license status) ---
        if (sourceLower === 'oup') {
            if (rightsType !== 'RF') {
                getOrCreateFlaggedRecord(i).reasons.push(`For OUP, Rights Type must be "RF", but is "${rightsType}".`);
            }
        }


        // --- Other Validation Rules ---

        // Rule: Not-empty validation for specified columns
        const columnsToAssertNotEmpty = [
            { name: 'Usage Classification', index: columnIndices.usageColIndex },
            { name: 'Description', index: columnIndices.descColIndex },
            { name: 'Library Image no', index: columnIndices.imgNoColIndex },
            { name: 'Source', index: columnIndices.sourceColIndex },
            { name: 'Rights type', index: columnIndices.rightsColIndex },
            { name: 'Acknowledgement', index: columnIndices.ackColIndex },
            { name: 'Page number', index: columnIndices.pageColIndex },
            { name: 'Photolog creation', index: columnIndices.photologColIndex },
            { name: 'Notes', index: columnIndices.notesColIndex },
        ];

        const emptyColumns: string[] = [];
        columnsToAssertNotEmpty.forEach(col => {
            if (col.index === undefined) return;
            const cellValue = row[col.index];
            if (cellValue === null || cellValue === undefined || String(cellValue).trim() === '') {
                emptyColumns.push(col.name);
            }
        });

        if (emptyColumns.length > 0) {
            const flaggedRecord = getOrCreateFlaggedRecord(i);
            flaggedRecord.reasons.push(`Required column${emptyColumns.length > 1 ? 's' : ''} empty: ${emptyColumns.join(', ')}.`);
        }

        // Rule: PO Number must exist for licensed usage
        if (columnIndices.poNumColIndex !== undefined) {
            if (isLicensed) {
                const poNumber = row[columnIndices.poNumColIndex];
                if (poNumber === null || poNumber === undefined || String(poNumber).trim() === '') {
                    const flaggedRecord = getOrCreateFlaggedRecord(i);
                    flaggedRecord.reasons.push(`Usage is "${usageClassification}" but PO Number is empty.`);
                }
            }
        }
    }

    // --- GLOBAL VALIDATION (REUSE PAIRING) ---
    const imageNoGroups = new Map<string, number[]>();
    for (let i = headerRowIndex + 1; i <= lastDataRowIndex; i++) {
        const row = rawData[i];
        if (!Array.isArray(row)) continue;
        const imageNo = String(row[columnIndices.imgNoColIndex] || '').trim();
        if (imageNo) {
            if (!imageNoGroups.has(imageNo)) {
                imageNoGroups.set(imageNo, []);
            }
            imageNoGroups.get(imageNo)!.push(i);
        }
    }

    for (const [imageNo, rowIndices] of imageNoGroups.entries()) {
        if (rowIndices.length === 1) {
            continue; // Orphans are not considered an error in this validation.
        }

        const rowNumbers = rowIndices.map(rowIndex => rowIndex + 1).join(', ');
        const pageNumbers = rowIndices.map(rowIndex => {
            const row = rawData[rowIndex];
            return String(row[columnIndices.pageColIndex] || 'N/A').trim();
        }).join(', ');

        if (rowIndices.length > 2) {
            const reason = `Image Used Too Many Times: '${imageNo}' appears ${rowIndices.length} times on rows ${rowNumbers} (pages: ${pageNumbers}). An image number should appear exactly twice for a reuse pair.`;
            for (const rowIndex of rowIndices) {
                getOrCreateFlaggedRecord(rowIndex).reasons.push(reason);
            }
            continue;
        }

        // We have exactly 2 rows.
        const [indexA, indexB] = rowIndices;
        const rowA = rawData[indexA];
        const rowB = rawData[indexB];

        // 1. Determine roles (main vs reuse)
        const notesA = String(rowA[columnIndices.notesColIndex] || '').trim().toLowerCase();
        const notesB = String(rowB[columnIndices.notesColIndex] || '').trim().toLowerCase();
        const isAReuse = notesA.includes('reuse');
        const isBReuse = notesB.includes('reuse');

        let mainRowIndex: number | null = null;
        let reuseRowIndex: number | null = null;

        if (isAReuse && !isBReuse) {
            mainRowIndex = indexB;
            reuseRowIndex = indexA;
        } else if (!isAReuse && isBReuse) {
            mainRowIndex = indexA;
            reuseRowIndex = indexB;
        } else {
            const roleError = isAReuse && isBReuse 
                ? `Ambiguous Pair (Conflicted): Image No "${imageNo}" (rows ${rowNumbers}) has 'reuse' in Notes for both entries. Only one is allowed.`
                : `Ambiguous Pair (Missing Role): Image No "${imageNo}" (rows ${rowNumbers}) is missing a 'reuse' entry in Notes for one of the entries.`;

            getOrCreateFlaggedRecord(indexA).reasons.push(roleError);
            getOrCreateFlaggedRecord(indexB).reasons.push(roleError);
            continue; // Can't proceed with pair validation without clear roles
        }

        const mainRow = rawData[mainRowIndex];
        const reuseRow = rawData[reuseRowIndex];
        const pairErrors: string[] = [];

        // 2. Check for Consistency across the pair
        const mainDesc = String(mainRow[columnIndices.descColIndex] || '').trim();
        const reuseDesc = String(reuseRow[columnIndices.descColIndex] || '').trim();
        const mainSource = String(mainRow[columnIndices.sourceColIndex] || '').trim();
        const reuseSource = String(reuseRow[columnIndices.sourceColIndex] || '').trim();
        const mainRights = String(mainRow[columnIndices.rightsColIndex] || '').trim();
        const reuseRights = String(reuseRow[columnIndices.rightsColIndex] || '').trim();

        const inconsistencies = [];
        if (mainDesc !== reuseDesc) inconsistencies.push(`Description ('${mainDesc}' vs '${reuseDesc}')`);
        if (mainSource !== reuseSource) inconsistencies.push(`Source ('${mainSource}' vs '${reuseSource}')`);
        if (mainRights !== reuseRights) inconsistencies.push(`Rights Type ('${mainRights}' vs '${reuseRights}')`);

        if (inconsistencies.length > 0) {
            pairErrors.push(`Inconsistent Pair Data: The pair for Image No "${imageNo}" has mismatching data for ${inconsistencies.join(', ')}.`);
        }

        // 3. Check 'New'/'Pickup' consistency
        const mainUsage = String(mainRow[columnIndices.usageColIndex] || '').trim();
        const reuseUsage = String(reuseRow[columnIndices.usageColIndex] || '').trim();
        const normalizedMainUsage = normalizeText(mainUsage);
        const normalizedReuseUsage = normalizeText(reuseUsage);

        const mainIsNew = normalizedMainUsage.includes('new');
        const mainIsPickup = normalizedMainUsage.includes('pickup') || normalizedMainUsage.includes('pick up');
        const reuseIsNew = normalizedReuseUsage.includes('new');
        const reuseIsPickup = normalizedReuseUsage.includes('pickup') || normalizedReuseUsage.includes('pick up');

        if ((mainIsNew && !reuseIsNew) || (mainIsPickup && !reuseIsPickup)) {
            pairErrors.push(`Inconsistent Pair Status: Mismatching 'New'/'Pickup' status between main entry ("${mainUsage}") and reuse entry ("${reuseUsage}").`);
        }

        // Apply any collected pair-level errors to both records
        if (pairErrors.length > 0) {
            const combinedReason = pairErrors.join(' ');
            getOrCreateFlaggedRecord(mainRowIndex).reasons.push(combinedReason);
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(combinedReason);
        }

        // 4. Validate the Reuse Entry specifically
        const reuseEntryErrors: string[] = [];
        if (normalizedReuseUsage.includes('license') && !normalizedReuseUsage.includes('no license')) {
            reuseEntryErrors.push(`Malformed Reuse Entry: The reuse entry (row ${reuseRowIndex + 1}) must have a non-licensed Usage, but found "${reuseUsage}".`);
        }

        const reuseFeeValue = reuseRow[columnIndices.feeColIndex];
        const reuseFee = (reuseFeeValue === null || reuseFeeValue === undefined) ? '' : String(reuseFeeValue).trim();

        if (reuseIsNew) { // Corresponds to "New/No License"
            if (reuseFee !== '0') {
                 reuseEntryErrors.push(`Malformed Reuse Entry: The reuse entry (row ${reuseRowIndex + 1}) is 'New/No License' but fee is not 0. Found "${reuseFee}".`);
            }
        } else if (reuseIsPickup) { // Corresponds to "Pickup/No License"
            if (reuseFee !== '') {
                 reuseEntryErrors.push(`Malformed Reuse Entry: The reuse entry (row ${reuseRowIndex + 1}) is 'Pickup/No License' but fee is not blank. Found "${reuseFee}".`);
            }
        }

        // Apply reuse-entry-specific errors ONLY to the reuse record
        if (reuseEntryErrors.length > 0) {
            const combinedReason = reuseEntryErrors.join(' ');
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(combinedReason);
        }
    }

    // --- FINAL ASSEMBLY ---
    const finalFlags: AIFlaggedRecord[] = [];
    for (const record of recordsMap.values()) {
        if (record.reasons.length > 0) {
            // Join reasons into the single string property
            record.reason = record.reasons.join(REASON_SEPARATOR);
            // Remove the temporary `reasons` property before pushing
            const { reasons, ...finalRecord } = record;
            finalFlags.push(finalRecord);
        }
    }

    return finalFlags;
};

import type { AcknowledgementRecord, ProcessedExcelData, HeaderIndices } from '../types';

const findMetadata = (data: (string | number)[][]): { isbn: string | null, title: string | null } => {
    let isbn: string | null = null;
    let title: string | null = null;
    const searchDepth = 5; // Search the first 5 rows for metadata

    for (let r = 0; r < Math.min(data.length, searchDepth); r++) {
        const row = data[r];
        if (!Array.isArray(row)) continue;

        for (let c = 0; c < row.length - 1; c++) {
            const cellValue = String(row[c]).toLowerCase().trim();
            const nextCellValue = String(row[c + 1]).trim();

            if (cellValue.includes('isbn') && !isbn) {
                isbn = nextCellValue;
            }
            if (cellValue.includes('title') && !title) {
                title = nextCellValue;
            }
        }
        if (isbn && title) break; // Stop searching once both are found
    }
    return { isbn, title };
};


const findHeaders = (data: (string | number)[][]): {
  headerRowIndex: number;
  columnIndices: HeaderIndices;
} => {
  let headerRowIndex = -1;
  let columnIndices: Partial<HeaderIndices> = {};

  // Map header names to keys in HeaderIndices. We include aliases like 'jc comments' for 'notes'.
  const headerMap: { [key: string]: keyof HeaderIndices } = {
    'source': 'sourceColIndex',
    'acknowledgement': 'ackColIndex',
    'page number': 'pageColIndex',
    'usage classification': 'usageColIndex',
    'licence fee': 'feeColIndex',
    'description': 'descColIndex',
    'library image no': 'imgNoColIndex',
    'rights type': 'rightsColIndex',
    'photolog creation': 'photologColIndex',
    'notes': 'notesColIndex',
    'jc comments': 'notesColIndex', // Alias for notes
    'po number': 'poNumColIndex'
  };

  const requiredKeys: (keyof HeaderIndices)[] = [
    'sourceColIndex',
    'ackColIndex',
    'pageColIndex',
    'usageColIndex',
    'feeColIndex',
    'descColIndex',
    'imgNoColIndex',
    'rightsColIndex',
    'photologColIndex',
    'notesColIndex'
  ];

  for (let i = 0; i < data.length; i++) {
    const row = data[i];
    if (!Array.isArray(row)) continue;

    const lowerCaseRow = row.map(cell =>
      typeof cell === 'string' ? cell.toLowerCase().trim().replace(/\s*\(.*\)\s*$/, '') : ''
    );

    const tempIndices: Partial<HeaderIndices> = {};

    // Check all headers in the map
    for (const headerName in headerMap) {
        const index = lowerCaseRow.indexOf(headerName);
        if (index !== -1) {
            // If multiple headers map to the same key (like 'notes' and 'jc comments'), 
            // the first one found in the row wins.
            if (tempIndices[headerMap[headerName]] === undefined) {
                tempIndices[headerMap[headerName]] = index;
            }
        }
    }

    // Check if all required keys were filled
    const missingRequired = requiredKeys.filter(key => tempIndices[key] === undefined);

    if (missingRequired.length === 0) {
      headerRowIndex = i;
      columnIndices = tempIndices;
      break; 
    }
  }

  if (headerRowIndex === -1) {
    const missingCols: string[] = [];
    // To give a good error, we find the most likely header row and check it
    const mostLikelyHeaderRow = data.find(row => Array.isArray(row) && row.some(cell => typeof cell === 'string' && cell.toLowerCase().includes('source'))) || [];
    const lowerCaseCheckRow = mostLikelyHeaderRow.map(cell => typeof cell === 'string' ? cell.toLowerCase().trim().replace(/\s*\(.*\)\s*$/, '') : '');

    const requiredNames = ['source', 'acknowledgement', 'page number', 'usage classification', 'licence fee', 'description', 'library image no', 'rights type', 'photolog creation', 'notes'];

    for (const name of requiredNames) {
        if (!lowerCaseCheckRow.includes(name) && !(name === 'notes' && lowerCaseCheckRow.includes('jc comments'))) {
            missingCols.push(`"${name}"`);
        }
    }

    if (missingCols.length > 0) {
        throw new Error(`Could not find all required columns. Missing: ${missingCols.join(', ')}. Please check the Excel file headers.`);
    }
    throw new Error('Could not find a valid header row containing all required columns.');
  }

  return { headerRowIndex, columnIndices: columnIndices as HeaderIndices };
};


export const processExcelFile = (file: File): Promise<ProcessedExcelData> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e: ProgressEvent<FileReader>) => {
      try {
        // @ts-ignore
        const XLSX = window.XLSX;
        if (!XLSX) {
            throw new Error('The library for reading Excel files (xlsx) could not be found. Please check your internet connection and try again.');
        }

        if (!e.target?.result) {
          return reject(new Error('Failed to read file.'));
        }

        const data = new Uint8Array(e.target.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });

        let processedData: ProcessedExcelData | null = null;

        for (const sheetName of workbook.SheetNames) {
            const worksheet = workbook.Sheets[sheetName];
            const jsonData: (string | number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

            if (jsonData.length === 0) continue;

            try {
                const { headerRowIndex, columnIndices } = findHeaders(jsonData);
                const metadata = findMetadata(jsonData);

                const sheetRecords: AcknowledgementRecord[] = [];
                for (let i = headerRowIndex + 1; i < jsonData.length; i++) {
                    const row = jsonData[i];
                    if (!Array.isArray(row)) continue;

                    const source = row[columnIndices.sourceColIndex];
                    const acknowledgement = row[columnIndices.ackColIndex];

                    if (source && acknowledgement) {
                        sheetRecords.push({
                            source: String(source).trim(),
                            acknowledgement: String(acknowledgement).trim(),
                            pageNumber: String(row[columnIndices.pageColIndex] || '').trim(),
                            usageClassification: String(row[columnIndices.usageColIndex] || '').trim(),
                            licenseFee: String(row[columnIndices.feeColIndex] || '').trim(),
                            originalRowIndex: i,
                            description: String(row[columnIndices.descColIndex] || '').trim(),
                            libraryImageNo: String(row[columnIndices.imgNoColIndex] || '').trim(),
                            rightsType: String(row[columnIndices.rightsColIndex] || '').trim(),
                            photologCreation: String(row[columnIndices.photologColIndex] || '').trim(),
                            notes: String(row[columnIndices.notesColIndex] || '').trim(),
                            poNumber: columnIndices.poNumColIndex !== undefined ? String(row[columnIndices.poNumColIndex] || '').trim() : undefined,
                        });
                    }
                }

                processedData = {
                    records: sheetRecords,
                    isbn: metadata.isbn,
                    title: metadata.title,
                    rawData: jsonData,
                    headerRowIndex: headerRowIndex,
                    columnIndices: columnIndices,
                };
                break; // Found and processed the correct sheet, exit loop
            } catch (error) {
                // Headers not in this sheet, continue to the next
                continue;
            }
        }

        if (processedData === null) {
            return reject(new Error('Could not find required columns in any sheet. Please check your Excel file.'));
        }

        if (processedData.records.length === 0) {
            reject(new Error("No data rows found under the required headers."));
        } else {
            resolve(processedData);
        }

      } catch (error) {
        if (error instanceof Error) {
            reject(error);
        } else {
            reject(new Error('An unknown error occurred during file processing.'));
        }
      }
    };

    reader.onerror = (error) => {
      reject(new Error('File reading error: ' + error));
    };

    reader.readAsArrayBuffer(file);
  });
};

import type { AIFlaggedRecord, HeaderIndices } from '../types';

const normalizeText = (text: string): string => {
    // Treat hyphens, slashes as word separators and ignore case.
    return (text || '').toLowerCase().replace(/[-/]/g, ' ');
};

/**
 * Validates records based on a set of concrete rules.
 * @param rawData - The raw data array from the Excel sheet.
 * @param headerRowIndex - The index of the header row.
 * @param columnIndices - An object mapping column names to their indices.
 * @returns An array of flagged records with reasons for the flag.
 */
export const validateData = (
    rawData: (string | number)[][],
    headerRowIndex: number,
    columnIndices: HeaderIndices
): AIFlaggedRecord[] => {
    // Use a temporary type for the map to hold the array of reasons
    type TempFlaggedRecord = AIFlaggedRecord & { reasons: string[] };
    const recordsMap = new Map<number, TempFlaggedRecord>();
    const REASON_SEPARATOR = '|||';

    const getOrCreateFlaggedRecord = (rowIndex: number): TempFlaggedRecord => {
        if (recordsMap.has(rowIndex)) {
            return recordsMap.get(rowIndex)!;
        }
        const row = rawData[rowIndex];
        const record: TempFlaggedRecord = {
            source: String(row[columnIndices.sourceColIndex] || '').trim(),
            acknowledgement: String(row[columnIndices.ackColIndex] || '').trim(),
            pageNumber: String(row[columnIndices.pageColIndex] || '').trim(),
            usageClassification: String(row[columnIndices.usageColIndex] || '').trim(),
            licenseFee: String(row[columnIndices.feeColIndex] || '').trim(),
            originalRowIndex: rowIndex,
            reason: '', // Will be populated at the end
            reasons: [],
        };
        recordsMap.set(rowIndex, record);
        return record;
    };

    // Find the last row that is considered a valid entry.
    let lastDataRowIndex = -1;
    for (let i = rawData.length - 1; i > headerRowIndex; i--) {
        const row = rawData[i];
        if (Array.isArray(row)) {
            const sourceCell = row[columnIndices.sourceColIndex];
            const ackCell = row[columnIndices.ackColIndex];

            const source = (sourceCell === null || sourceCell === undefined) ? '' : String(sourceCell).trim();
            const acknowledgement = (ackCell === null || ackCell === undefined) ? '' : String(ackCell).trim();

            const hasSource = source !== '' && source !== '.';
            const hasAck = acknowledgement !== '' && acknowledgement !== '.';

            if (hasSource && hasAck) {
                lastDataRowIndex = i;
                break;
            }
        }
    }

    if (lastDataRowIndex === -1) {
        return [];
    }

    // --- ROW-BY-ROW VALIDATION ---
    for (let i = headerRowIndex + 1; i <= lastDataRowIndex; i++) {
        const row = rawData[i];
        if (!Array.isArray(row)) continue;

        const source = String(row[columnIndices.sourceColIndex] || '').trim();
        const rightsType = String(row[columnIndices.rightsColIndex] || '').trim().toUpperCase();

        // This index points to 'Notes' or 'JC Comments' depending on what was found in headers.
        const notes = String(row[columnIndices.notesColIndex] || '').trim().toLowerCase();

        // Rule: "needs replacing as per pickup" (or "pick-up") exception
        const isReplacingAsPerPickup = notes.includes('needs replacing as per pickup') || notes.includes('needs replacing as per pick-up');

        const licenseFeeValue = row[columnIndices.feeColIndex];
        const licenseFeeStr = (licenseFeeValue === null || licenseFeeValue === undefined) ? '' : String(licenseFeeValue).trim();

        const licenseFee = parseFloat(licenseFeeStr);
        const usageClassification = String(row[columnIndices.usageColIndex] || '').trim();
        const normalizedUsage = normalizeText(usageClassification);
        const sourceLower = source.toLowerCase();
        const isLicensed = normalizedUsage.includes('license') && !normalizedUsage.includes('no license');

        // --- License-Dependent Fee Validation ---
        if (isLicensed) {
            // Apply rules for licensed usage
            if (sourceLower === 'shutterstock') {
                if (rightsType === 'RF' && licenseFee !== 10) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Shutterstock/RF, fee must be 10, but is "${licenseFeeStr}".`);
                } else if (rightsType === 'RM' && licenseFee !== 40) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Shutterstock/RM, fee must be 40, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'getty images') {
                if (rightsType === 'RF' && licenseFee !== 17.5) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Getty Images/RF, fee must be 17.5, but is "${licenseFeeStr}".`);
                } else if (rightsType === 'RM' && licenseFee !== 40) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Getty Images/RM, fee must be 40, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'alamy') {
                if (licenseFeeStr !== '' && ![0, 29, 45].includes(licenseFee)) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Alamy, licensed fee must be 0, 29, or 45, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'oup') {
                getOrCreateFlaggedRecord(i).reasons.push(`For OUP, Usage must not contain "License", but is "${usageClassification}".`);
            } else {
                if (licenseFeeStr === '' || isNaN(licenseFee) || licenseFee <= 0) {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is licensed but Licence Fee ("${licenseFeeStr || 'empty'}") is not a positive number.`);
                }
            }
        } else { // Not licensed
            if (normalizedUsage.includes('new') && normalizedUsage.includes('no license')) {
                // For "New/No License", the fee must be 0...
                // UNLESS it's flagged as "needs replacing as per pickup" in the JC Comments
                if (isReplacingAsPerPickup) {
                    // If it is replacing as per pickup, it doesn't need 0, and should ideally be blank.
                    if (licenseFeeStr !== '') {
                        getOrCreateFlaggedRecord(i).reasons.push(`For New/No License usage marked "Replacing as per pickup", fee should be blank, but is "${licenseFeeStr}".`);
                    }
                } else {
                    if (licenseFee !== 0) {
                        getOrCreateFlaggedRecord(i).reasons.push(`For New/No License usage, fee must be 0, but is "${licenseFeeStr}".`);
                    }
                }
            } else if ((normalizedUsage.includes('pickup') || normalizedUsage.includes('pick up')) && normalizedUsage.includes('no license')) {
                // For "Pickup/No License", the fee must be blank.
                if (licenseFeeStr !== '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Pickup/No License usage, fee must be blank, but is "${licenseFeeStr}".`);
                }
            } else {
                if (licenseFeeStr !== '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is not licensed and not specified as New/Pickup, but Licence Fee is not empty ("${licenseFeeStr}").`);
                }
            }
        }

        if (sourceLower === 'oup') {
            if (rightsType !== 'RF') {
                getOrCreateFlaggedRecord(i).reasons.push(`For OUP, Rights Type must be "RF", but is "${rightsType}".`);
            }
        }

        const columnsToAssertNotEmpty = [
            { name: 'Usage Classification', index: columnIndices.usageColIndex },
            { name: 'Description', index: columnIndices.descColIndex },
            { name: 'Library Image no', index: columnIndices.imgNoColIndex },
            { name: 'Source', index: columnIndices.sourceColIndex },
            { name: 'Rights type', index: columnIndices.rightsColIndex },
            { name: 'Acknowledgement', index: columnIndices.ackColIndex },
            { name: 'Page number', index: columnIndices.pageColIndex },
            { name: 'Photolog creation', index: columnIndices.photologColIndex },
            { name: 'Notes', index: columnIndices.notesColIndex },
        ];

        const emptyColumns: string[] = [];
        columnsToAssertNotEmpty.forEach(col => {
            if (col.index === undefined) return;
            const cellValue = row[col.index];
            if (cellValue === null || cellValue === undefined || String(cellValue).trim() === '') {
                emptyColumns.push(col.name);
            }
        });

        if (emptyColumns.length > 0) {
            getOrCreateFlaggedRecord(i).reasons.push(`Required column${emptyColumns.length > 1 ? 's' : ''} empty: ${emptyColumns.join(', ')}.`);
        }

        if (columnIndices.poNumColIndex !== undefined) {
            if (isLicensed) {
                const poNumber = row[columnIndices.poNumColIndex];
                if (poNumber === null || poNumber === undefined || String(poNumber).trim() === '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is "${usageClassification}" but PO Number is empty.`);
                }
            }
        }
    }

    // --- GLOBAL VALIDATION (REUSE PAIRING) ---
    const imageNoGroups = new Map<string, number[]>();
    for (let i = headerRowIndex + 1; i <= lastDataRowIndex; i++) {
        const row = rawData[i];
        if (!Array.isArray(row)) continue;
        const imageNo = String(row[columnIndices.imgNoColIndex] || '').trim();
        if (imageNo) {
            if (!imageNoGroups.has(imageNo)) {
                imageNoGroups.set(imageNo, []);
            }
            imageNoGroups.get(imageNo)!.push(i);
        }
    }

    for (const [imageNo, rowIndices] of imageNoGroups.entries()) {
        if (rowIndices.length === 1) continue;

        const rowNumbers = rowIndices.map(rowIndex => rowIndex + 1).join(', ');
        const pageNumbers = rowIndices.map(rowIndex => String(rawData[rowIndex][columnIndices.pageColIndex] || 'N/A').trim()).join(', ');

        if (rowIndices.length > 2) {
            const reason = `Image Used Too Many Times: '${imageNo}' appears ${rowIndices.length} times on rows ${rowNumbers} (pages: ${pageNumbers}). An image number should appear exactly twice for a reuse pair.`;
            for (const rowIndex of rowIndices) {
                getOrCreateFlaggedRecord(rowIndex).reasons.push(reason);
            }
            continue;
        }

        const [indexA, indexB] = rowIndices;
        const notesA = String(rawData[indexA][columnIndices.notesColIndex] || '').trim().toLowerCase();
        const notesB = String(rawData[indexB][columnIndices.notesColIndex] || '').trim().toLowerCase();
        const isAReuse = notesA.includes('reuse');
        const isBReuse = notesB.includes('reuse');

        let mainRowIndex: number | null = null;
        let reuseRowIndex: number | null = null;

        if (isAReuse && !isBReuse) {
            mainRowIndex = indexB;
            reuseRowIndex = indexA;
        } else if (!isAReuse && isBReuse) {
            mainRowIndex = indexA;
            reuseRowIndex = indexB;
        } else {
            const roleError = isAReuse && isBReuse 
                ? `Ambiguous Pair (Conflicted): Image No "${imageNo}" (rows ${rowNumbers}) has 'reuse' in Notes for both entries. Only one is allowed.`
                : `Ambiguous Pair (Missing Role): Image No "${imageNo}" (rows ${rowNumbers}) is missing a 'reuse' entry in Notes for one of the entries.`;

            getOrCreateFlaggedRecord(indexA).reasons.push(roleError);
            getOrCreateFlaggedRecord(indexB).reasons.push(roleError);
            continue;
        }

        const mainRow = rawData[mainRowIndex];
        const reuseRow = rawData[reuseRowIndex];
        const pairErrors: string[] = [];

        if (String(mainRow[columnIndices.descColIndex]).trim() !== String(reuseRow[columnIndices.descColIndex]).trim()) pairErrors.push("Inconsistent Description.");
        if (String(mainRow[columnIndices.sourceColIndex]).trim() !== String(reuseRow[columnIndices.sourceColIndex]).trim()) pairErrors.push("Inconsistent Source.");
        if (String(mainRow[columnIndices.rightsColIndex]).trim() !== String(reuseRow[columnIndices.rightsColIndex]).trim()) pairErrors.push("Inconsistent Rights Type.");

        if (pairErrors.length > 0) {
            const combinedReason = `Inconsistent Pair Data for Image No "${imageNo}": ${pairErrors.join(' ')}`;
            getOrCreateFlaggedRecord(mainRowIndex).reasons.push(combinedReason);
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(combinedReason);
        }

        const mainUsage = String(mainRow[columnIndices.usageColIndex] || '').trim();
        const reuseUsage = String(reuseRow[columnIndices.usageColIndex] || '').trim();
        const normalizedMainUsage = normalizeText(mainUsage);
        const normalizedReuseUsage = normalizeText(reuseUsage);

        if (((normalizedMainUsage.includes('new')) && !normalizedReuseUsage.includes('new')) || 
            ((normalizedMainUsage.includes('pickup') || normalizedMainUsage.includes('pick up')) && !(normalizedReuseUsage.includes('pickup') || normalizedReuseUsage.includes('pick up')))) {
            const statusError = `Inconsistent Pair Status: Mismatching 'New'/'Pickup' status between main entry and reuse entry.`;
            getOrCreateFlaggedRecord(mainRowIndex).reasons.push(statusError);
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(statusError);
        }

        if (normalizedReuseUsage.includes('license') && !normalizedReuseUsage.includes('no license')) {
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: The reuse entry must have a non-licensed Usage.`);
        }

        const reuseFeeStr = String(reuseRow[columnIndices.feeColIndex] || '').trim();
        if (normalizedReuseUsage.includes('new')) {
            if (reuseFeeStr !== '0') getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: The reuse entry is 'New/No License' but fee is not 0.`);
        } else if (normalizedReuseUsage.includes('pickup') || normalizedReuseUsage.includes('pick up')) {
            if (reuseFeeStr !== '') getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: The reuse entry is 'Pickup/No License' but fee is not blank.`);
        }
    }

    const finalFlags: AIFlaggedRecord[] = [];
    for (const record of recordsMap.values()) {
        if (record.reasons.length > 0) {
            record.reason = record.reasons.join(REASON_SEPARATOR);
            const { reasons, ...finalRecord } = record;
            finalFlags.push(finalRecord);
        }
    }

    return finalFlags;
};

import type { AcknowledgementRecord, ProcessedExcelData, HeaderIndices } from '../types';

const findMetadata = (data: (string | number)[][]): { isbn: string | null, title: string | null } => {
    let isbn: string | null = null;
    let title: string | null = null;
    const searchDepth = 5; // Search the first 5 rows for metadata

    for (let r = 0; r < Math.min(data.length, searchDepth); r++) {
        const row = data[r];
        if (!Array.isArray(row)) continue;

        for (let c = 0; c < row.length - 1; c++) {
            const cellValue = String(row[c]).toLowerCase().trim();
            const nextCellValue = String(row[c + 1]).trim();

            if (cellValue.includes('isbn') && !isbn) {
                isbn = nextCellValue;
            }
            if (cellValue.includes('title') && !title) {
                title = nextCellValue;
            }
        }
        if (isbn && title) break; // Stop searching once both are found
    }
    return { isbn, title };
};


const findHeaders = (data: (string | number)[][]): {
  headerRowIndex: number;
  columnIndices: HeaderIndices;
} => {
  let headerRowIndex = -1;
  let columnIndices: Partial<HeaderIndices> = {};

  // Map header names to keys in HeaderIndices. 
  // We prioritize 'jc comments' over 'notes' as per user request.
  const headerMap: { [key: string]: keyof HeaderIndices } = {
    'source': 'sourceColIndex',
    'acknowledgement': 'ackColIndex',
    'page number': 'pageColIndex',
    'usage classification': 'usageColIndex',
    'licence fee': 'feeColIndex',
    'description': 'descColIndex',
    'library image no': 'imgNoColIndex',
    'rights type': 'rightsColIndex',
    'photolog creation': 'photologColIndex',
    'jc comments': 'notesColIndex', // Primary
    'notes': 'notesColIndex',        // Secondary fallback
    'po number': 'poNumColIndex'
  };

  const requiredKeys: (keyof HeaderIndices)[] = [
    'sourceColIndex',
    'ackColIndex',
    'pageColIndex',
    'usageColIndex',
    'feeColIndex',
    'descColIndex',
    'imgNoColIndex',
    'rightsColIndex',
    'photologColIndex',
    'notesColIndex'
  ];

  for (let i = 0; i < data.length; i++) {
    const row = data[i];
    if (!Array.isArray(row)) continue;

    const lowerCaseRow = row.map(cell =>
      typeof cell === 'string' ? cell.toLowerCase().trim().replace(/\s*\(.*\)\s*$/, '') : ''
    );

    const tempIndices: Partial<HeaderIndices> = {};

    // Check all headers in the map
    // We iterate in order, but since multiple names can map to the same key,
    // we should be careful about which index we pick.
    for (const headerName in headerMap) {
        const index = lowerCaseRow.indexOf(headerName);
        if (index !== -1) {
            const key = headerMap[headerName];
            // If the key is already set, we only overwrite it if the current headerName is 'jc comments'
            // because we want to prioritize it.
            if (tempIndices[key] === undefined || headerName === 'jc comments') {
                tempIndices[key] = index;
            }
        }
    }

    // Check if all required keys were filled
    const missingRequired = requiredKeys.filter(key => tempIndices[key] === undefined);

    if (missingRequired.length === 0) {
      headerRowIndex = i;
      columnIndices = tempIndices;
      break; 
    }
  }

  if (headerRowIndex === -1) {
    const missingCols: string[] = [];
    const mostLikelyHeaderRow = data.find(row => Array.isArray(row) && row.some(cell => typeof cell === 'string' && cell.toLowerCase().includes('source'))) || [];
    const lowerCaseCheckRow = mostLikelyHeaderRow.map(cell => typeof cell === 'string' ? cell.toLowerCase().trim().replace(/\s*\(.*\)\s*$/, '') : '');

    const requiredNames = ['source', 'acknowledgement', 'page number', 'usage classification', 'licence fee', 'description', 'library image no', 'rights type', 'photolog creation', 'notes'];

    for (const name of requiredNames) {
        if (!lowerCaseCheckRow.includes(name) && !(name === 'notes' && (lowerCaseCheckRow.includes('jc comments') || lowerCaseCheckRow.includes('notes')))) {
            missingCols.push(`"${name}"`);
        }
    }

    if (missingCols.length > 0) {
        throw new Error(`Could not find all required columns. Missing: ${missingCols.join(', ')}. Please check the Excel file headers.`);
    }
    throw new Error('Could not find a valid header row containing all required columns.');
  }

  return { headerRowIndex, columnIndices: columnIndices as HeaderIndices };
};


export const processExcelFile = (file: File): Promise<ProcessedExcelData> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e: ProgressEvent<FileReader>) => {
      try {
        // @ts-ignore
        const XLSX = window.XLSX;
        if (!XLSX) {
            throw new Error('The library for reading Excel files (xlsx) could not be found. Please check your internet connection and try again.');
        }

        if (!e.target?.result) {
          return reject(new Error('Failed to read file.'));
        }

        const data = new Uint8Array(e.target.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });

        let processedData: ProcessedExcelData | null = null;

        for (const sheetName of workbook.SheetNames) {
            const worksheet = workbook.Sheets[sheetName];
            const jsonData: (string | number)[][] = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

            if (jsonData.length === 0) continue;

            try {
                const { headerRowIndex, columnIndices } = findHeaders(jsonData);
                const metadata = findMetadata(jsonData);

                const sheetRecords: AcknowledgementRecord[] = [];
                for (let i = headerRowIndex + 1; i < jsonData.length; i++) {
                    const row = jsonData[i];
                    if (!Array.isArray(row)) continue;

                    const source = row[columnIndices.sourceColIndex];
                    const acknowledgement = row[columnIndices.ackColIndex];

                    if (source && acknowledgement) {
                        sheetRecords.push({
                            source: String(source).trim(),
                            acknowledgement: String(acknowledgement).trim(),
                            pageNumber: String(row[columnIndices.pageColIndex] || '').trim(),
                            usageClassification: String(row[columnIndices.usageColIndex] || '').trim(),
                            licenseFee: String(row[columnIndices.feeColIndex] || '').trim(),
                            originalRowIndex: i,
                            description: String(row[columnIndices.descColIndex] || '').trim(),
                            libraryImageNo: String(row[columnIndices.imgNoColIndex] || '').trim(),
                            rightsType: String(row[columnIndices.rightsColIndex] || '').trim(),
                            photologCreation: String(row[columnIndices.photologColIndex] || '').trim(),
                            notes: String(row[columnIndices.notesColIndex] || '').trim(),
                            poNumber: columnIndices.poNumColIndex !== undefined ? String(row[columnIndices.poNumColIndex] || '').trim() : undefined,
                        });
                    }
                }

                processedData = {
                    records: sheetRecords,
                    isbn: metadata.isbn,
                    title: metadata.title,
                    rawData: jsonData,
                    headerRowIndex: headerRowIndex,
                    columnIndices: columnIndices,
                };
                break; // Found and processed the correct sheet, exit loop
            } catch (error) {
                // Headers not in this sheet, continue to the next
                continue;
            }
        }

        if (processedData === null) {
            return reject(new Error('Could not find required columns in any sheet. Please check your Excel file.'));
        }

        if (processedData.records.length === 0) {
            reject(new Error("No data rows found under the required headers."));
        } else {
            resolve(processedData);
        }

      } catch (error) {
        if (error instanceof Error) {
            reject(error);
        } else {
            reject(new Error('An unknown error occurred during file processing.'));
        }
      }
    };

    reader.onerror = (error) => {
      reject(new Error('File reading error: ' + error));
    };

    reader.readAsArrayBuffer(file);
  });
};

import type { AIFlaggedRecord, HeaderIndices } from '../types';

const normalizeText = (text: string): string => {
    // Treat hyphens, slashes as word separators and ignore case.
    return (text || '').toLowerCase().replace(/[-/]/g, ' ');
};

/**
 * Validates records based on a set of concrete rules.
 * @param rawData - The raw data array from the Excel sheet.
 * @param headerRowIndex - The index of the header row.
 * @param columnIndices - An object mapping column names to their indices.
 * @returns An array of flagged records with reasons for the flag.
 */
export const validateData = (
    rawData: (string | number)[][],
    headerRowIndex: number,
    columnIndices: HeaderIndices
): AIFlaggedRecord[] => {
    // Use a temporary type for the map to hold the array of reasons
    type TempFlaggedRecord = AIFlaggedRecord & { reasons: string[] };
    const recordsMap = new Map<number, TempFlaggedRecord>();
    const REASON_SEPARATOR = '|||';

    const getOrCreateFlaggedRecord = (rowIndex: number): TempFlaggedRecord => {
        if (recordsMap.has(rowIndex)) {
            return recordsMap.get(rowIndex)!;
        }
        const row = rawData[rowIndex];
        const record: TempFlaggedRecord = {
            source: String(row[columnIndices.sourceColIndex] || '').trim(),
            acknowledgement: String(row[columnIndices.ackColIndex] || '').trim(),
            pageNumber: String(row[columnIndices.pageColIndex] || '').trim(),
            usageClassification: String(row[columnIndices.usageColIndex] || '').trim(),
            licenseFee: String(row[columnIndices.feeColIndex] || '').trim(),
            originalRowIndex: rowIndex,
            reason: '', // Will be populated at the end
            reasons: [],
        };
        recordsMap.set(rowIndex, record);
        return record;
    };

    // Find the last row that is considered a valid entry.
    let lastDataRowIndex = -1;
    for (let i = rawData.length - 1; i > headerRowIndex; i--) {
        const row = rawData[i];
        if (Array.isArray(row)) {
            const sourceCell = row[columnIndices.sourceColIndex];
            const ackCell = row[columnIndices.ackColIndex];

            const source = (sourceCell === null || sourceCell === undefined) ? '' : String(sourceCell).trim();
            const acknowledgement = (ackCell === null || ackCell === undefined) ? '' : String(ackCell).trim();

            const hasSource = source !== '' && source !== '.';
            const hasAck = acknowledgement !== '' && acknowledgement !== '.';

            if (hasSource && hasAck) {
                lastDataRowIndex = i;
                break;
            }
        }
    }

    if (lastDataRowIndex === -1) {
        return [];
    }

    // --- ROW-BY-ROW VALIDATION ---
    for (let i = headerRowIndex + 1; i <= lastDataRowIndex; i++) {
        const row = rawData[i];
        if (!Array.isArray(row)) continue;

        const source = String(row[columnIndices.sourceColIndex] || '').trim();
        const rightsType = String(row[columnIndices.rightsColIndex] || '').trim().toUpperCase();

        // This index points to 'Notes' or 'JC Comments' depending on what was found in headers.
        const notes = String(row[columnIndices.notesColIndex] || '').trim().toLowerCase();

        // Rule: "needs replacing as per pickup" (or "pick-up") exception
        const isReplacingAsPerPickup = notes.includes('needs replacing as per pickup') || notes.includes('needs replacing as per pick-up');

        const licenseFeeValue = row[columnIndices.feeColIndex];
        const licenseFeeStr = (licenseFeeValue === null || licenseFeeValue === undefined) ? '' : String(licenseFeeValue).trim();

        const licenseFee = parseFloat(licenseFeeStr);
        const usageClassification = String(row[columnIndices.usageColIndex] || '').trim();
        const normalizedUsage = normalizeText(usageClassification);
        const sourceLower = source.toLowerCase();
        const isLicensed = normalizedUsage.includes('license') && !normalizedUsage.includes('no license');

        // --- License-Dependent Fee Validation ---
        if (isLicensed) {
            // Apply rules for licensed usage
            if (sourceLower === 'shutterstock') {
                if (rightsType === 'RF' && licenseFee !== 10) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Shutterstock/RF, fee must be 10, but is "${licenseFeeStr}".`);
                } else if (rightsType === 'RM' && licenseFee !== 40) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Shutterstock/RM, fee must be 40, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'getty images') {
                if (rightsType === 'RF' && licenseFee !== 17.5) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Getty Images/RF, fee must be 17.5, but is "${licenseFeeStr}".`);
                } else if (rightsType === 'RM' && licenseFee !== 40) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Getty Images/RM, fee must be 40, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'alamy') {
                if (licenseFeeStr !== '' && ![0, 29, 45].includes(licenseFee)) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Alamy, licensed fee must be 0, 29, or 45, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'oup') {
                getOrCreateFlaggedRecord(i).reasons.push(`For OUP, Usage must not contain "License", but is "${usageClassification}".`);
            } else {
                if (licenseFeeStr === '' || isNaN(licenseFee) || licenseFee <= 0) {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is licensed but Licence Fee ("${licenseFeeStr || 'empty'}") is not a positive number.`);
                }
            }
        } else { // Not licensed
            if (normalizedUsage.includes('new') && normalizedUsage.includes('no license')) {
                // For "New/No License", the fee must be 0...
                // UNLESS it's flagged as "needs replacing as per pickup" in the JC Comments
                if (isReplacingAsPerPickup) {
                    // If it is replacing as per pickup, it doesn't need 0. Both 0 and blank are acceptable.
                    if (licenseFeeStr !== '' && licenseFeeStr !== '0') {
                        getOrCreateFlaggedRecord(i).reasons.push(`For New/No License usage marked "Replacing as per pickup", fee should be blank or 0, but is "${licenseFeeStr}".`);
                    }
                } else {
                    if (licenseFeeStr !== '0') {
                        getOrCreateFlaggedRecord(i).reasons.push(`For New/No License usage, fee must be 0, but is "${licenseFeeStr}".`);
                    }
                }
            } else if ((normalizedUsage.includes('pickup') || normalizedUsage.includes('pick up')) && normalizedUsage.includes('no license')) {
                // For "Pickup/No License", the fee must be blank.
                if (licenseFeeStr !== '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Pickup/No License usage, fee must be blank, but is "${licenseFeeStr}".`);
                }
            } else {
                if (licenseFeeStr !== '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is not licensed and not specified as New/Pickup, but Licence Fee is not empty ("${licenseFeeStr}").`);
                }
            }
        }

        if (sourceLower === 'oup') {
            if (rightsType !== 'RF') {
                getOrCreateFlaggedRecord(i).reasons.push(`For OUP, Rights Type must be "RF", but is "${rightsType}".`);
            }
        }

        const columnsToAssertNotEmpty = [
            { name: 'Usage Classification', index: columnIndices.usageColIndex },
            { name: 'Description', index: columnIndices.descColIndex },
            { name: 'Library Image no', index: columnIndices.imgNoColIndex },
            { name: 'Source', index: columnIndices.sourceColIndex },
            { name: 'Rights type', index: columnIndices.rightsColIndex },
            { name: 'Acknowledgement', index: columnIndices.ackColIndex },
            { name: 'Page number', index: columnIndices.pageColIndex },
            { name: 'Photolog creation', index: columnIndices.photologColIndex },
            { name: 'Notes', index: columnIndices.notesColIndex },
        ];

        const emptyColumns: string[] = [];
        columnsToAssertNotEmpty.forEach(col => {
            if (col.index === undefined) return;
            const cellValue = row[col.index];
            if (cellValue === null || cellValue === undefined || String(cellValue).trim() === '') {
                emptyColumns.push(col.name);
            }
        });

        if (emptyColumns.length > 0) {
            getOrCreateFlaggedRecord(i).reasons.push(`Required column${emptyColumns.length > 1 ? 's' : ''} empty: ${emptyColumns.join(', ')}.`);
        }

        if (columnIndices.poNumColIndex !== undefined) {
            if (isLicensed) {
                const poNumber = row[columnIndices.poNumColIndex];
                if (poNumber === null || poNumber === undefined || String(poNumber).trim() === '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is "${usageClassification}" but PO Number is empty.`);
                }
            }
        }
    }

    // --- GLOBAL VALIDATION (REUSE PAIRING) ---
    const imageNoGroups = new Map<string, number[]>();
    for (let i = headerRowIndex + 1; i <= lastDataRowIndex; i++) {
        const row = rawData[i];
        if (!Array.isArray(row)) continue;
        const imageNo = String(row[columnIndices.imgNoColIndex] || '').trim();
        if (imageNo) {
            if (!imageNoGroups.has(imageNo)) {
                imageNoGroups.set(imageNo, []);
            }
            imageNoGroups.get(imageNo)!.push(i);
        }
    }

    for (const [imageNo, rowIndices] of imageNoGroups.entries()) {
        if (rowIndices.length === 1) continue;

        const rowNumbers = rowIndices.map(rowIndex => rowIndex + 1).join(', ');
        const pageNumbers = rowIndices.map(rowIndex => String(rawData[rowIndex][columnIndices.pageColIndex] || 'N/A').trim()).join(', ');

        if (rowIndices.length > 2) {
            const reason = `Image Used Too Many Times: '${imageNo}' appears ${rowIndices.length} times on rows ${rowNumbers} (pages: ${pageNumbers}). An image number should appear exactly twice for a reuse pair.`;
            for (const rowIndex of rowIndices) {
                getOrCreateFlaggedRecord(rowIndex).reasons.push(reason);
            }
            continue;
        }

        const [indexA, indexB] = rowIndices;
        const notesA = String(rawData[indexA][columnIndices.notesColIndex] || '').trim().toLowerCase();
        const notesB = String(rawData[indexB][columnIndices.notesColIndex] || '').trim().toLowerCase();
        const isAReuse = notesA.includes('reuse');
        const isBReuse = notesB.includes('reuse');

        let mainRowIndex: number | null = null;
        let reuseRowIndex: number | null = null;

        if (isAReuse && !isBReuse) {
            mainRowIndex = indexB;
            reuseRowIndex = indexA;
        } else if (!isAReuse && isBReuse) {
            mainRowIndex = indexA;
            reuseRowIndex = indexB;
        } else {
            const roleError = isAReuse && isBReuse 
                ? `Ambiguous Pair (Conflicted): Image No "${imageNo}" (rows ${rowNumbers}) has 'reuse' in Notes for both entries. Only one is allowed.`
                : `Ambiguous Pair (Missing Role): Image No "${imageNo}" (rows ${rowNumbers}) is missing a 'reuse' entry in Notes for one of the entries.`;

            getOrCreateFlaggedRecord(indexA).reasons.push(roleError);
            getOrCreateFlaggedRecord(indexB).reasons.push(roleError);
            continue;
        }

        const mainRow = rawData[mainRowIndex];
        const reuseRow = rawData[reuseRowIndex];
        const pairErrors: string[] = [];

        if (String(mainRow[columnIndices.descColIndex]).trim() !== String(reuseRow[columnIndices.descColIndex]).trim()) pairErrors.push("Inconsistent Description.");
        if (String(mainRow[columnIndices.sourceColIndex]).trim() !== String(reuseRow[columnIndices.sourceColIndex]).trim()) pairErrors.push("Inconsistent Source.");
        if (String(mainRow[columnIndices.rightsColIndex]).trim() !== String(reuseRow[columnIndices.rightsColIndex]).trim()) pairErrors.push("Inconsistent Rights Type.");

        if (pairErrors.length > 0) {
            const combinedReason = `Inconsistent Pair Data for Image No "${imageNo}": ${pairErrors.join(' ')}`;
            getOrCreateFlaggedRecord(mainRowIndex).reasons.push(combinedReason);
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(combinedReason);
        }

        const mainUsage = String(mainRow[columnIndices.usageColIndex] || '').trim();
        const reuseUsage = String(reuseRow[columnIndices.usageColIndex] || '').trim();
        const normalizedMainUsage = normalizeText(mainUsage);
        const normalizedReuseUsage = normalizeText(reuseUsage);

        if (((normalizedMainUsage.includes('new')) && !normalizedReuseUsage.includes('new')) || 
            ((normalizedMainUsage.includes('pickup') || normalizedMainUsage.includes('pick up')) && !(normalizedReuseUsage.includes('pickup') || normalizedReuseUsage.includes('pick up')))) {
            const statusError = `Inconsistent Pair Status: Mismatching 'New'/'Pickup' status between main entry and reuse entry.`;
            getOrCreateFlaggedRecord(mainRowIndex).reasons.push(statusError);
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(statusError);
        }

        if (normalizedReuseUsage.includes('license') && !normalizedReuseUsage.includes('no license')) {
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: The reuse entry must have a non-licensed Usage.`);
        }

        const reuseFeeStr = String(reuseRow[columnIndices.feeColIndex] || '').trim();
        const reuseNotes = String(reuseRow[columnIndices.notesColIndex] || '').trim().toLowerCase();
        const reuseIsReplacingAsPerPickup = reuseNotes.includes('needs replacing as per pickup') || reuseNotes.includes('needs replacing as per pick-up');

        if (normalizedReuseUsage.includes('new')) {
            if (reuseIsReplacingAsPerPickup) {
                 if (reuseFeeStr !== '0' && reuseFeeStr !== '') {
                      getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: The reuse entry is 'New/No License' marked "Replacing as per pickup" but fee is neither 0 nor blank.`);
                 }
            } else if (reuseFeeStr !== '0') {
                 getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: The reuse entry is 'New/No License' but fee is not 0.`);
            }
        } else if (normalizedReuseUsage.includes('pickup') || normalizedReuseUsage.includes('pick up')) {
            if (reuseFeeStr !== '') getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: The reuse entry is 'Pickup/No License' but fee is not blank.`);
        }
    }

    const finalFlags: AIFlaggedRecord[] = [];
    for (const record of recordsMap.values()) {
        if (record.reasons.length > 0) {
            record.reason = record.reasons.join(REASON_SEPARATOR);
            const { reasons, ...finalRecord } = record;
            finalFlags.push(finalRecord);
        }
    }

    return finalFlags;
};

import type { AIFlaggedRecord, HeaderIndices } from '../types';

const normalizeText = (text: string): string => {
    // Treat hyphens, slashes as word separators and ignore case.
    return (text || '').toLowerCase().replace(/[-/]/g, ' ');
};

/**
 * Validates records based on a set of concrete rules.
 * @param rawData - The raw data array from the Excel sheet.
 * @param headerRowIndex - The index of the header row.
 * @param columnIndices - An object mapping column names to their indices.
 * @returns An array of flagged records with reasons for the flag.
 */
export const validateData = (
    rawData: (string | number)[][],
    headerRowIndex: number,
    columnIndices: HeaderIndices
): AIFlaggedRecord[] => {
    // Use a temporary type for the map to hold the array of reasons
    type TempFlaggedRecord = AIFlaggedRecord & { reasons: string[] };
    const recordsMap = new Map<number, TempFlaggedRecord>();
    const REASON_SEPARATOR = '|||';

    const getOrCreateFlaggedRecord = (rowIndex: number): TempFlaggedRecord => {
        if (recordsMap.has(rowIndex)) {
            return recordsMap.get(rowIndex)!;
        }
        const row = rawData[rowIndex];
        const record: TempFlaggedRecord = {
            source: String(row[columnIndices.sourceColIndex] || '').trim(),
            acknowledgement: String(row[columnIndices.ackColIndex] || '').trim(),
            pageNumber: String(row[columnIndices.pageColIndex] || '').trim(),
            usageClassification: String(row[columnIndices.usageColIndex] || '').trim(),
            licenseFee: String(row[columnIndices.feeColIndex] || '').trim(),
            originalRowIndex: rowIndex,
            reason: '', // Will be populated at the end
            reasons: [],
        };
        recordsMap.set(rowIndex, record);
        return record;
    };

    // Find the last row that is considered a valid entry.
    let lastDataRowIndex = -1;
    for (let i = rawData.length - 1; i > headerRowIndex; i--) {
        const row = rawData[i];
        if (Array.isArray(row)) {
            const sourceCell = row[columnIndices.sourceColIndex];
            const ackCell = row[columnIndices.ackColIndex];

            const source = (sourceCell === null || sourceCell === undefined) ? '' : String(sourceCell).trim();
            const acknowledgement = (ackCell === null || ackCell === undefined) ? '' : String(ackCell).trim();

            const hasSource = source !== '' && source !== '.';
            const hasAck = acknowledgement !== '' && acknowledgement !== '.';

            if (hasSource && hasAck) {
                lastDataRowIndex = i;
                break;
            }
        }
    }

    if (lastDataRowIndex === -1) {
        return [];
    }

    // --- ROW-BY-ROW VALIDATION ---
    for (let i = headerRowIndex + 1; i <= lastDataRowIndex; i++) {
        const row = rawData[i];
        if (!Array.isArray(row)) continue;

        const source = String(row[columnIndices.sourceColIndex] || '').trim();
        const rightsType = String(row[columnIndices.rightsColIndex] || '').trim().toUpperCase();

        // This index points to 'Notes' or 'JC Comments' depending on what was found in headers.
        const notes = String(row[columnIndices.notesColIndex] || '').trim().toLowerCase();

        const licenseFeeValue = row[columnIndices.feeColIndex];
        const licenseFeeStr = (licenseFeeValue === null || licenseFeeValue === undefined) ? '' : String(licenseFeeValue).trim();

        const licenseFee = parseFloat(licenseFeeStr);
        const usageClassification = String(row[columnIndices.usageColIndex] || '').trim();
        const normalizedUsage = normalizeText(usageClassification);
        const sourceLower = source.toLowerCase();

        // Key definitions
        const hasNoLicense = normalizedUsage.includes('no license');
        const isLicensed = normalizedUsage.includes('license') && !hasNoLicense;

        // --- License-Dependent Fee Validation ---
        if (hasNoLicense) {
            // Simplify: fee column has to be empty if 'usage classification' contains "No License"
            if (licenseFeeStr !== '') {
                getOrCreateFlaggedRecord(i).reasons.push(`For No License usage, Licence Fee must be blank, but is "${licenseFeeStr}".`);
            }
        } else if (isLicensed) {
            // Apply rules for licensed usage
            if (sourceLower === 'shutterstock') {
                if (rightsType === 'RF' && licenseFee !== 10) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Shutterstock/RF, fee must be 10, but is "${licenseFeeStr}".`);
                } else if (rightsType === 'RM' && licenseFee !== 40) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Shutterstock/RM, fee must be 40, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'getty images') {
                if (rightsType === 'RF' && licenseFee !== 17.5) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Getty Images/RF, fee must be 17.5, but is "${licenseFeeStr}".`);
                } else if (rightsType === 'RM' && licenseFee !== 40) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Getty Images/RM, fee must be 40, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'alamy') {
                if (licenseFeeStr !== '' && ![0, 29, 45].includes(licenseFee)) {
                    getOrCreateFlaggedRecord(i).reasons.push(`For Alamy, licensed fee must be 0, 29, or 45, but is "${licenseFeeStr}".`);
                }
            } else if (sourceLower === 'oup') {
                getOrCreateFlaggedRecord(i).reasons.push(`For OUP, Usage must not contain "License", but is "${usageClassification}".`);
            } else {
                if (licenseFeeStr === '' || isNaN(licenseFee) || licenseFee <= 0) {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is licensed but Licence Fee ("${licenseFeeStr || 'empty'}") is not a positive number.`);
                }
            }
        } else { 
            // Neither "No License" nor "License" found explicitly or other state
            if (licenseFeeStr !== '') {
                getOrCreateFlaggedRecord(i).reasons.push(`Usage is not specified as Licensed or No License, but Licence Fee is not empty ("${licenseFeeStr}").`);
            }
        }

        if (sourceLower === 'oup') {
            if (rightsType !== 'RF') {
                getOrCreateFlaggedRecord(i).reasons.push(`For OUP, Rights Type must be "RF", but is "${rightsType}".`);
            }
        }

        const columnsToAssertNotEmpty = [
            { name: 'Usage Classification', index: columnIndices.usageColIndex },
            { name: 'Description', index: columnIndices.descColIndex },
            { name: 'Library Image no', index: columnIndices.imgNoColIndex },
            { name: 'Source', index: columnIndices.sourceColIndex },
            { name: 'Rights type', index: columnIndices.rightsColIndex },
            { name: 'Acknowledgement', index: columnIndices.ackColIndex },
            { name: 'Page number', index: columnIndices.pageColIndex },
            { name: 'Photolog creation', index: columnIndices.photologColIndex },
            { name: 'Notes', index: columnIndices.notesColIndex },
        ];

        const emptyColumns: string[] = [];
        columnsToAssertNotEmpty.forEach(col => {
            if (col.index === undefined) return;
            const cellValue = row[col.index];
            if (cellValue === null || cellValue === undefined || String(cellValue).trim() === '') {
                emptyColumns.push(col.name);
            }
        });

        if (emptyColumns.length > 0) {
            getOrCreateFlaggedRecord(i).reasons.push(`Required column${emptyColumns.length > 1 ? 's' : ''} empty: ${emptyColumns.join(', ')}.`);
        }

        if (columnIndices.poNumColIndex !== undefined) {
            if (isLicensed) {
                const poNumber = row[columnIndices.poNumColIndex];
                if (poNumber === null || poNumber === undefined || String(poNumber).trim() === '') {
                    getOrCreateFlaggedRecord(i).reasons.push(`Usage is "${usageClassification}" but PO Number is empty.`);
                }
            }
        }
    }

    // --- GLOBAL VALIDATION (REUSE PAIRING) ---
    const imageNoGroups = new Map<string, number[]>();
    for (let i = headerRowIndex + 1; i <= lastDataRowIndex; i++) {
        const row = rawData[i];
        if (!Array.isArray(row)) continue;
        const imageNo = String(row[columnIndices.imgNoColIndex] || '').trim();
        if (imageNo) {
            if (!imageNoGroups.has(imageNo)) {
                imageNoGroups.set(imageNo, []);
            }
            imageNoGroups.get(imageNo)!.push(i);
        }
    }

    for (const [imageNo, rowIndices] of imageNoGroups.entries()) {
        if (rowIndices.length === 1) continue;

        const rowNumbers = rowIndices.map(rowIndex => rowIndex + 1).join(', ');
        const pageNumbers = rowIndices.map(rowIndex => String(rawData[rowIndex][columnIndices.pageColIndex] || 'N/A').trim()).join(', ');

        if (rowIndices.length > 2) {
            const reason = `Image Used Too Many Times: '${imageNo}' appears ${rowIndices.length} times on rows ${rowNumbers} (pages: ${pageNumbers}). An image number should appear exactly twice for a reuse pair.`;
            for (const rowIndex of rowIndices) {
                getOrCreateFlaggedRecord(rowIndex).reasons.push(reason);
            }
            continue;
        }

        const [indexA, indexB] = rowIndices;
        const notesA = String(rawData[indexA][columnIndices.notesColIndex] || '').trim().toLowerCase();
        const notesB = String(rawData[indexB][columnIndices.notesColIndex] || '').trim().toLowerCase();
        const isAReuse = notesA.includes('reuse');
        const isBReuse = notesB.includes('reuse');

        let mainRowIndex: number | null = null;
        let reuseRowIndex: number | null = null;

        if (isAReuse && !isBReuse) {
            mainRowIndex = indexB;
            reuseRowIndex = indexA;
        } else if (!isAReuse && isBReuse) {
            mainRowIndex = indexA;
            reuseRowIndex = indexB;
        } else {
            const roleError = isAReuse && isBReuse 
                ? `Ambiguous Pair (Conflicted): Image No "${imageNo}" (rows ${rowNumbers}) has 'reuse' in Notes for both entries. Only one is allowed.`
                : `Ambiguous Pair (Missing Role): Image No "${imageNo}" (rows ${rowNumbers}) is missing a 'reuse' entry in Notes for one of the entries.`;

            getOrCreateFlaggedRecord(indexA).reasons.push(roleError);
            getOrCreateFlaggedRecord(indexB).reasons.push(roleError);
            continue;
        }

        const mainRow = rawData[mainRowIndex];
        const reuseRow = rawData[reuseRowIndex];
        const pairErrors: string[] = [];

        if (String(mainRow[columnIndices.descColIndex]).trim() !== String(reuseRow[columnIndices.descColIndex]).trim()) pairErrors.push("Inconsistent Description.");
        if (String(mainRow[columnIndices.sourceColIndex]).trim() !== String(reuseRow[columnIndices.sourceColIndex]).trim()) pairErrors.push("Inconsistent Source.");
        if (String(mainRow[columnIndices.rightsColIndex]).trim() !== String(reuseRow[columnIndices.rightsColIndex]).trim()) pairErrors.push("Inconsistent Rights Type.");

        if (pairErrors.length > 0) {
            const combinedReason = `Inconsistent Pair Data for Image No "${imageNo}": ${pairErrors.join(' ')}`;
            getOrCreateFlaggedRecord(mainRowIndex).reasons.push(combinedReason);
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(combinedReason);
        }

        const mainUsage = String(mainRow[columnIndices.usageColIndex] || '').trim();
        const reuseUsage = String(reuseRow[columnIndices.usageColIndex] || '').trim();
        const normalizedMainUsage = normalizeText(mainUsage);
        const normalizedReuseUsage = normalizeText(reuseUsage);

        if (((normalizedMainUsage.includes('new')) && !normalizedReuseUsage.includes('new')) || 
            ((normalizedMainUsage.includes('pickup') || normalizedMainUsage.includes('pick up')) && !(normalizedReuseUsage.includes('pickup') || normalizedReuseUsage.includes('pick up')))) {
            const statusError = `Inconsistent Pair Status: Mismatching 'New'/'Pickup' status between main entry and reuse entry.`;
            getOrCreateFlaggedRecord(mainRowIndex).reasons.push(statusError);
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(statusError);
        }

        if (normalizedReuseUsage.includes('license') && !normalizedReuseUsage.includes('no license')) {
            getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: The reuse entry must have a non-licensed Usage.`);
        }

        // Reuse entry fee logic follows the "No License" rule
        const reuseFeeStr = String(reuseRow[columnIndices.feeColIndex] || '').trim();
        if (normalizedReuseUsage.includes('no license')) {
            if (reuseFeeStr !== '') {
                getOrCreateFlaggedRecord(reuseRowIndex).reasons.push(`Malformed Reuse Entry: For No License usage, Licence Fee must be blank, but is "${reuseFeeStr}".`);
            }
        }
    }

    const finalFlags: AIFlaggedRecord[] = [];
    for (const record of recordsMap.values()) {
        if (record.reasons.length > 0) {
            record.reason = record.reasons.join(REASON_SEPARATOR);
            const { reasons, ...finalRecord } = record;
            finalFlags.push(finalRecord);
        }
    }

    return finalFlags;
};
